script:
frappe.ui.form.on('Disciplinary', {
    refresh: function(frm) {
        // Lock employee_response field in all states except "Fill in Exculpation"
        lock_employee_response_field(frm);
        
        // Check if document is in "Issue Charge" workflow state
        if (frm.doc.workflow_state === 'Issue Charge') {
            check_and_restrict_fields(frm);
        }
        
        // Check if document is in "Fill in Exculpation" workflow state
        if (frm.doc.workflow_state === 'Fill in Exculpation') {
            check_exculpation_access(frm);
        }
        
        // Check if document is in "Exculpation Evaluation" workflow state
        if (frm.doc.workflow_state === 'Exculpation Evaluation') {
            check_evaluation_access(frm);
        }
        
        // Check if document is in "Hearing Recommended" workflow state
        if (frm.doc.workflow_state === 'Hearing Recommended') {
            handle_hearing_recommended_state(frm);
        }
        
        // Check if document is in "Employee Hearing Outcome Evaluation" workflow state
        if (frm.doc.workflow_state === 'Employee Hearing Outcome Evaluation') {
            restrict_employee_hearing_outcome_actions(frm);
        }
    },
    
    workflow_state: function(frm) {
        // Lock employee_response field in all states except "Fill in Exculpation"
        lock_employee_response_field(frm);
        
        // Trigger when workflow state changes
        if (frm.doc.workflow_state === 'Issue Charge') {
            check_and_restrict_fields(frm);
        }
        
        // Trigger for Fill in Exculpation state
        if (frm.doc.workflow_state === 'Fill in Exculpation') {
            check_exculpation_access(frm);
        }
        
        // Trigger for Exculpation Evaluation state
        if (frm.doc.workflow_state === 'Exculpation Evaluation') {
            check_evaluation_access(frm);
        }
        
        // Trigger for Hearing Recommended state
        if (frm.doc.workflow_state === 'Hearing Recommended') {
            handle_hearing_recommended_state(frm);
        }
        
        // Trigger for Employee Hearing Outcome Evaluation state
        if (frm.doc.workflow_state === 'Employee Hearing Outcome Evaluation') {
            restrict_employee_hearing_outcome_actions(frm);
        }
    },
    
    employee: function(frm) {
        // Re-check restrictions when employee is changed
        if (frm.doc.workflow_state === 'Issue Charge') {
            check_and_restrict_fields(frm);
        }
        
        // Re-check for exculpation state
        if (frm.doc.workflow_state === 'Fill in Exculpation') {
            check_exculpation_access(frm);
        }
        
        // Re-check for evaluation state
        if (frm.doc.workflow_state === 'Exculpation Evaluation') {
            check_evaluation_access(frm);
        }
        
        // Re-check for Employee Hearing Outcome Evaluation state
        if (frm.doc.workflow_state === 'Employee Hearing Outcome Evaluation') {
            restrict_employee_hearing_outcome_actions(frm);
        }
    },
    
    before_workflow_action: function(frm) {
        // Block workflow actions in "Employee Hearing Outcome Evaluation" if user is not the employee
        if (frm.doc.workflow_state === 'Employee Hearing Outcome Evaluation') {
            const current_user = frappe.session.user;
            let is_employee = false;
            
            // Check synchronously if current user is the employee
            if (frm.doc.employee) {
                frappe.call({
                    method: 'frappe.client.get_value',
                    args: {
                        doctype: 'Employee',
                        filters: { name: frm.doc.employee },
                        fieldname: 'user_id'
                    },
                    async: false,
                    callback: function(response) {
                        if (response.message) {
                            const employee_user = response.message.user_id;
                            is_employee = (current_user === employee_user);
                        }
                    }
                });
                
                // If not the employee, prevent workflow action
                if (!is_employee) {
                    frappe.msgprint({
                        title: __('Access Denied'),
                        indicator: 'red',
                        message: __('Only the employee can perform workflow actions in "Employee Hearing Outcome Evaluation" state.')
                    });
                    frappe.validated = false;
                    return false;
                }
            } else {
                // No employee selected, block action
                frappe.msgprint({
                    title: __('Error'),
                    indicator: 'red',
                    message: __('No employee is selected in this document.')
                });
                frappe.validated = false;
                return false;
            }
        }
    }
});

function check_and_restrict_fields(frm) {
    // Get current user
    const current_user = frappe.session.user;
    
    // Check if user has Supervisor role
    if (frappe.user.has_role('Supervisor')) {
        // Get the employee's reporting supervisor
        if (frm.doc.employee) {
            frappe.call({
                method: 'frappe.client.get_value',
                args: {
                    doctype: 'Employee',
                    filters: { name: frm.doc.employee },
                    fieldname: 'reports_to'
                },
                callback: function(response) {
                    if (response.message) {
                        const reports_to_employee = response.message.reports_to;
                        
                        if (reports_to_employee) {
                            // Get the user_id of the reporting supervisor
                            frappe.call({
                                method: 'frappe.client.get_value',
                                args: {
                                    doctype: 'Employee',
                                    filters: { name: reports_to_employee },
                                    fieldname: 'user_id'
                                },
                                callback: function(supervisor_response) {
                                    if (supervisor_response.message) {
                                        const supervisor_user = supervisor_response.message.user_id;
                                        
                                        // If current user is NOT the initiating supervisor
                                        if (current_user !== supervisor_user) {
                                            // Make all fields read-only
                                            disable_all_fields(frm);
                                            
                                            frappe.msgprint({
                                                title: __('Access Restricted'),
                                                indicator: 'red',
                                                message: __('You cannot edit this document in "Issue Charge" state. Only the initiating Supervisor can make changes.')
                                            });
                                        }
                                    }
                                }
                            });
                        }
                    }
                }
            });
        } else {
            // If no employee is selected, restrict all supervisors
            disable_all_fields(frm);
        }
    }
}

function disable_all_fields(frm) {
    // Get all fields in the form
    frm.fields.forEach(function(field) {
        // Skip standard fields that should remain functional
        if (!['amended_from', 'workflow_state'].includes(field.df.fieldname)) {
            frm.set_df_property(field.df.fieldname, 'read_only', 1);
        }
    });
    
    // Disable the form save button
    frm.disable_save();
    
    // Also disable any child table fields if present
    Object.keys(frm.fields_dict).forEach(function(fieldname) {
        const field = frm.fields_dict[fieldname];
        if (field.grid) {
            field.grid.wrapper.find('.grid-add-row').hide();
            field.grid.wrapper.find('.grid-remove-rows').hide();
            field.grid.wrapper.find('.grid-row').each(function() {
                $(this).find('input, textarea, select, button').prop('disabled', true);
            });
        }
    });
}

function check_exculpation_access(frm) {
    // Get current user
    const current_user = frappe.session.user;
    
    // Check if employee is selected
    if (frm.doc.employee) {
        // Get the user_id of the selected employee
        frappe.call({
            method: 'frappe.client.get_value',
            args: {
                doctype: 'Employee',
                filters: { name: frm.doc.employee },
                fieldname: 'user_id'
            },
            callback: function(response) {
                if (response.message) {
                    const employee_user = response.message.user_id;
                    
                    // If current user is NOT the employee in the document
                    if (current_user !== employee_user) {
                        // Make all fields read-only
                        disable_all_fields_exculpation(frm);
                        
                        frappe.msgprint({
                            title: __('Access Restricted'),
                            indicator: 'red',
                            message: __('You cannot edit this document in "Fill in Exculpation" state. Only the employee can fill in their response.')
                        });
                    } else {
                        // Current user IS the employee - restrict all fields except employee_response
                        restrict_to_response_field_only(frm);
                        
                        frappe.show_alert({
                            message: __('You can only edit the "Employee Response" field in this state.'),
                            indicator: 'blue'
                        }, 5);
                    }
                }
            }
        });
    } else {
        // If no employee is selected, restrict everyone
        disable_all_fields_exculpation(frm);
    }
}

function disable_all_fields_exculpation(frm) {
    // Get all fields in the form
    frm.fields.forEach(function(field) {
        // Skip standard fields that should remain functional
        if (!['amended_from', 'workflow_state'].includes(field.df.fieldname)) {
            frm.set_df_property(field.df.fieldname, 'read_only', 1);
        }
    });
    
    // Disable the form save button
    frm.disable_save();
    
    // Also disable any child table fields if present
    Object.keys(frm.fields_dict).forEach(function(fieldname) {
        const field = frm.fields_dict[fieldname];
        if (field.grid) {
            field.grid.wrapper.find('.grid-add-row').hide();
            field.grid.wrapper.find('.grid-remove-rows').hide();
            field.grid.wrapper.find('.grid-row').each(function() {
                $(this).find('input, textarea, select, button').prop('disabled', true);
            });
        }
    });
}

function restrict_to_response_field_only(frm) {
    // Make all fields read-only EXCEPT employee_response
    frm.fields.forEach(function(field) {
        if (field.df.fieldname !== 'employee_response' && !['amended_from', 'workflow_state'].includes(field.df.fieldname)) {
            frm.set_df_property(field.df.fieldname, 'read_only', 1);
        } else if (field.df.fieldname === 'employee_response') {
            // Ensure employee_response is editable
            frm.set_df_property(field.df.fieldname, 'read_only', 0);
        }
    });
    
    // Disable any child table fields if present
    Object.keys(frm.fields_dict).forEach(function(fieldname) {
        const field = frm.fields_dict[fieldname];
        if (field.grid) {
            field.grid.wrapper.find('.grid-add-row').hide();
            field.grid.wrapper.find('.grid-remove-rows').hide();
            field.grid.wrapper.find('.grid-row').each(function() {
                $(this).find('input, textarea, select, button').prop('disabled', true);
            });
        }
    });
}

function check_evaluation_access(frm) {
    // Get current user
    const current_user = frappe.session.user;
    
    // Check if user has Supervisor role
    if (frappe.user.has_role('Supervisor')) {
        // Get the employee's reporting supervisor
        if (frm.doc.employee) {
            frappe.call({
                method: 'frappe.client.get_value',
                args: {
                    doctype: 'Employee',
                    filters: { name: frm.doc.employee },
                    fieldname: 'reports_to'
                },
                callback: function(response) {
                    if (response.message) {
                        const reports_to_employee = response.message.reports_to;
                        
                        if (reports_to_employee) {
                            // Get the user_id of the reporting supervisor
                            frappe.call({
                                method: 'frappe.client.get_value',
                                args: {
                                    doctype: 'Employee',
                                    filters: { name: reports_to_employee },
                                    fieldname: 'user_id'
                                },
                                callback: function(supervisor_response) {
                                    if (supervisor_response.message) {
                                        const supervisor_user = supervisor_response.message.user_id;
                                        
                                        // If current user is the initiating supervisor
                                        if (current_user === supervisor_user) {
                                            // Make all fields read-only - only workflow actions allowed
                                            disable_all_fields_evaluation(frm);
                                            
                                            frappe.show_alert({
                                                message: __('In "Exculpation Evaluation" state, you can only perform workflow actions. All fields are read-only.'),
                                                indicator: 'blue'
                                            }, 5);
                                        }
                                    }
                                }
                            });
                        }
                    }
                }
            });
        }
    }
}

function disable_all_fields_evaluation(frm) {
    // Get all fields in the form and make them read-only
    frm.fields.forEach(function(field) {
        // Skip workflow_state to allow workflow actions
        if (!['amended_from', 'workflow_state'].includes(field.df.fieldname)) {
            frm.set_df_property(field.df.fieldname, 'read_only', 1);
        }
    });
    
    // Disable the regular save button
    frm.disable_save();
    
    // Disable any child table fields if present
    Object.keys(frm.fields_dict).forEach(function(fieldname) {
        const field = frm.fields_dict[fieldname];
        if (field.grid) {
            field.grid.wrapper.find('.grid-add-row').hide();
            field.grid.wrapper.find('.grid-remove-rows').hide();
            field.grid.wrapper.find('.grid-row').each(function() {
                $(this).find('input, textarea, select, button').prop('disabled', true);
            });
        }
    });
}

function lock_employee_response_field(frm) {
    // Employee Response field can ONLY be edited in "Fill in Exculpation" state
    // Lock it in all other states
    if (frm.doc.workflow_state !== 'Fill in Exculpation') {
        frm.set_df_property('employee_response', 'read_only', 1);
    }
}

function handle_hearing_recommended_state(frm) {
    // Show and make hearing_date field mandatory and visible
    frm.set_df_property('hearing_date', 'hidden', 0);
    frm.set_df_property('hearing_date', 'read', 1);
    frm.set_df_property('hearing_date', 'read_only', 0);
    
    // Get all fields that belong to tab_4_tab and make them editable
    frm.fields.forEach(function(field) {
        // Check if the field belongs to tab_4_tab
        if (field.df.parent === 'tab_4_tab' || (field.df.fieldname && is_field_in_tab_4(field.df.fieldname, frm))) {
            // Make the field editable
            frm.set_df_property(field.df.fieldname, 'read_only', 0);
            // Show the field if it was hidden
            frm.set_df_property(field.df.fieldname, 'hidden', 0);
        }
    });
    
    // Enable save button
    frm.enable_save();
    
    // Show alert to user
    frappe.show_alert({
        message: __('Hearing Date is mandatory. All fields in Hearing tab are now editable.'),
        indicator: 'green'
    }, 7);
}

function is_field_in_tab_4(fieldname, frm) {
    // Helper function to check if a field belongs to tab_4_tab
    // This checks the field's parent in the doctype meta
    const field_meta = frappe.meta.get_docfield('Disciplinary', fieldname, frm.doc.name);
    if (field_meta) {
        // Check if the field's parent matches tab_4_tab or if it has the label indicating it's in that tab
        return field_meta.parent === 'tab_4_tab';
    }
    return false;
}

function restrict_employee_hearing_outcome_actions(frm) {
    // Get current user
    const current_user = frappe.session.user;
    
    // Check if employee is selected
    if (frm.doc.employee) {
        // Get the user_id of the selected employee
        frappe.call({
            method: 'frappe.client.get_value',
            args: {
                doctype: 'Employee',
                filters: { name: frm.doc.employee },
                fieldname: 'user_id'
            },
            async: false, // Make synchronous to set the flag before workflow action
            callback: function(response) {
                if (response.message) {
                    const employee_user = response.message.user_id;
                    
                    // Store the check result in the form object
                    frm._is_correct_employee_for_hearing = (current_user === employee_user);
                    
                    // If current user is NOT the employee in the document
                    if (current_user !== employee_user) {
                        // Hide all workflow action buttons
                        hide_workflow_buttons(frm);
                        
                        // Make all fields read-only
                        disable_all_fields_for_non_employee(frm);
                        
                        frappe.show_alert({
                            message: __('Only the employee can perform workflow actions in "Employee Hearing Outcome Evaluation" state.'),
                            indicator: 'red'
                        }, 7);
                    } else {
                        // Current user IS the employee - show workflow buttons and allow actions
                        frappe.show_alert({
                            message: __('You can now perform workflow actions on this document.'),
                            indicator: 'green'
                        }, 5);
                    }
                }
            }
        });
    } else {
        // If no employee is selected, restrict everyone
        frm._is_correct_employee_for_hearing = false;
        hide_workflow_buttons(frm);
        disable_all_fields_for_non_employee(frm);
    }
}

function hide_workflow_buttons(frm) {
    // Hide all workflow action buttons from the page
    setTimeout(function() {
        // Hide the workflow action buttons in the form
        frm.page.clear_actions();
        
        // Also hide the Actions menu dropdown that contains workflow actions
        frm.page.btn_secondary.hide();
        
        // Hide workflow state change buttons
        $('.form-workflow .btn-default').hide();
        $('.form-workflow .btn-primary').hide();
        
    }, 100);
}

function disable_all_fields_for_non_employee(frm) {
    // Get all fields in the form and make them read-only
    frm.fields.forEach(function(field) {
        // Skip standard fields
        if (!['amended_from', 'workflow_state'].includes(field.df.fieldname)) {
            frm.set_df_property(field.df.fieldname, 'read_only', 1);
        }
    });
    
    // Disable the form save button
    frm.disable_save();
    
    // Disable any child table fields if present
    Object.keys(frm.fields_dict).forEach(function(fieldname) {
        const field = frm.fields_dict[fieldname];
        if (field.grid) {
            field.grid.wrapper.find('.grid-add-row').hide();
            field.grid.wrapper.find('.grid-remove-rows').hide();
            field.grid.wrapper.find('.grid-row').each(function() {
                $(this).find('input, textarea, select, button').prop('disabled', true);
            });
        }
    });
}

frappe.ui.form.on("Goal", {
    refresh: function(frm) {
        frm.set_query("employee", function() {
            return {
                filters: {
                    reports_to: frappe.session.user
                }
            };
        });
    }
});

frappe.ui.form.on('Forced Leave', {
    // Trigger when Start Date or End Date changes
    start_date(frm) {
        calculate_days(frm);
    },
    end_date(frm) {
        calculate_days(frm);
    }
});

// Function to calculate total days
function calculate_days(frm) {
    if (frm.doc.start_date && frm.doc.end_date) {
        let start = frappe.datetime.str_to_obj(frm.doc.start_date);
        let end = frappe.datetime.str_to_obj(frm.doc.end_date);

        // Total days including both start and end date
        let total_days = (end - start) / (1000 * 60 * 60 * 24) + 1;

        // Ensure total_days is at least 0
        if (total_days < 0) {
            total_days = 0;
        }

        frm.set_value('days', total_days);
    } else {
        frm.set_value('days', 0);
    }
}

// ============================================================
// DISCIPLINARY FORM — Main Form Controller
// ============================================================

frappe.ui.form.on('Disciplinary', {

    offence_category: function(frm) {
        set_charge_offence_filter(frm);
    },

    refresh: function(frm) {
        frm.clear_custom_buttons();
        set_charge_offence_filter(frm);

        if (!frm.is_new()) {

            if (frm.doc.employee) {
                frm.add_custom_button(__('View Breach History'), function() {
                    show_breach_history(frm);
                }, __('Employee History'));

                frm.add_custom_button(__('View All Cases'), function() {
                    show_all_employee_cases(frm);
                }, __('Employee History'));
            }

            let first_charge = (frm.doc.charge_description || []).find(r => r.specific_offence);
            if (first_charge) {
                frm.add_custom_button(__('View Sanction Matrix'), function() {
                    show_sanction_matrix(frm, first_charge.specific_offence, first_charge.breach_number);
                }, __('Reference Info'));
            }

            if (frm.doc.employee && (frm.doc.charge_description || []).length > 0 && frm.doc.docstatus === 0) {
                frm.add_custom_button(__('Recalculate Breach'), function() {
                    frappe.msgprint({
                        title: __('Recalculating'),
                        message: __('Breach numbers will be recalculated for all charges. Please save the document.'),
                        indicator: 'blue'
                    });
                    frm.save();
                });
            }
        }
    }
});


// ============================================================
// DISCIPLINARY CHARGES — Child Table Controller
// ============================================================

frappe.ui.form.on('Disciplinary Charges', {

    specific_offence: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (!row.specific_offence) return;

        // Fetch offence details and populate description
        frappe.db.get_value(
            'Offence Master',
            row.specific_offence,
            ['offence_name', 'definition', 'offence_code'],
            function(r) {
                if (r) {
                    frappe.model.set_value(cdt, cdn, 'description', r.definition);
                    frappe.show_alert({
                        message: `<strong>${r.offence_code}: ${r.offence_name}</strong><br><br>${r.definition}`,
                        indicator: 'blue'
                    }, 15);
                }
            }
        );

        // Save first so Python can set breach_number, then fetch sanction
        if (frm.doc.employee) {
            frm.save().then(function() {
                // Re-read the row AFTER save — cdn is still valid, locals is refreshed
                let saved_row = locals[cdt] && locals[cdt][cdn];
                if (saved_row && saved_row.specific_offence && saved_row.breach_number) {
                    get_prescribed_sanction(frm, cdt, cdn);
                } else {
                    // Python didn't set breach_number — calculate it in JS
                    calculate_breach_then_fetch_sanction(frm, cdt, cdn);
                }
            });
        } else {
            get_prescribed_sanction(frm, cdt, cdn);
        }
    },

    breach_number: function(frm, cdt, cdn) {
        let row = locals[cdt] && locals[cdt][cdn];
        if (row && row.specific_offence && row.breach_number) {
            get_prescribed_sanction(frm, cdt, cdn);
        }
    },

    charge_description_remove: function(frm) {
        if (!frm.is_new() && frm.doc.employee) {
            frm.save();
        }
    },

    view_offence_details: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (row.specific_offence) {
            show_offence_details(row.specific_offence);
        } else {
            frappe.msgprint(__('Please select an offence first.'));
        }
    },

    view_sanction_matrix: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (row.specific_offence) {
            show_sanction_matrix(frm, row.specific_offence, row.breach_number);
        } else {
            frappe.msgprint(__('Please select an offence first.'));
        }
    }
});


// ============================================================
// HELPER FUNCTIONS
// ============================================================

function set_charge_offence_filter(frm) {
    // Guard against grid not being rendered yet
    if (!frm.fields_dict['charge_description'] || !frm.fields_dict['charge_description'].grid) return;

    frm.set_query('specific_offence', 'charge_description', function() {
        if (frm.doc.offence_category) {
            return { filters: { offence_category: frm.doc.offence_category } };
        }
        return {};
    });
}


// ============================================================
// FETCH SANCTION FROM MATRIX
// ============================================================

function get_prescribed_sanction(frm, cdt, cdn) {
    let row = locals[cdt] && locals[cdt][cdn];

    if (!row) {
        console.warn('get_prescribed_sanction: row not found for', cdt, cdn);
        return;
    }

    if (!row.specific_offence || !row.breach_number) {
        console.warn('get_prescribed_sanction: missing offence or breach_number', row);
        return;
    }

    frappe.db.get_value(
        'Offence Sanction Matrix',
        { offence: row.specific_offence, breach_number: row.breach_number },
        ['prescribed_sanction'],
        function(r) {
            if (r && r.prescribed_sanction) {
                frappe.model.set_value(cdt, cdn, 'prescribed_sanction', r.prescribed_sanction);
            } else {
                console.warn('No sanction found for:', row.specific_offence, row.breach_number);
            }
        }
    );
}


// ============================================================
// JS FALLBACK: Calculate breach number if Python didn't set it
// ============================================================

function calculate_breach_then_fetch_sanction(frm, cdt, cdn) {
    const breach_labels = ['1st Breach', '2nd Breach', '3rd Breach', '4th Breach'];

    frappe.call({
        method: 'frappe.client.get_count',
        args: {
            doctype: 'Disciplinary',
            filters: {
                employee: frm.doc.employee,
                name: ['!=', frm.doc.name],
                docstatus: 1
            }
        },
        callback: function(r) {
            let count = r.message || 0;
            let breach_value = breach_labels[Math.min(count, 3)];

            frappe.model.set_value(cdt, cdn, 'breach_number', breach_value).then(function() {
                get_prescribed_sanction(frm, cdt, cdn);
            });
        }
    });
}


