// ============================================================
// CORE FUNCTIONS
// ============================================================

/**
 * Calculates the correct breach number for a charge row.
 * Logic:
 *   1. Check ALL previous Disciplinary records for this employee with the same offence
 *   2. Only count breaches that are within the active warning window:
 *      - Verbal Warning: active for 6 months from date of issue
 *      - Written Warning: active for 12 months from date of issue
 *   3. The next breach number = count of active prior warnings + 1
 */
function calculate_breach_number(frm, row, cdt, cdn) {
    if (!frm.doc.employee || !row.specific_offence) return;

    const today = frappe.datetime.get_today();

    // Query all closed/completed disciplinary cases for this employee & offence
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Disciplinary',
            filters: [
                ['employee', '=', frm.doc.employee],
                ['name', '!=', frm.doc.name || ''],
                ['workflow_state', 'not in', ['Dropped', 'Draft']]
            ],
            fields: ['name'],
            limit_page_length: 200
        },
        callback(r) {
            if (!r.message || r.message.length === 0) {
                // No prior cases — this is 1st Breach
                set_breach_and_sanction(frm, cdt, cdn, row, '1st Breach');
                return;
            }

            // Now check charge rows within those cases for the same offence
            const prior_case_names = r.message.map(d => d.name);
            let active_warnings = [];
            let pending_calls = prior_case_names.length;

            prior_case_names.forEach((case_name) => {
                frappe.db.get_doc('Disciplinary', case_name).then((prior_doc) => {
                    if (prior_doc && prior_doc.charge_description) {
                        prior_doc.charge_description.forEach((charge) => {
                            if (charge.specific_offence === row.specific_offence) {
                                // Check if warning is still active
                                const expiry = charge.warning_expiry_date;
                                if (expiry && frappe.datetime.str_to_obj(expiry) >= frappe.datetime.str_to_obj(today)) {
                                    active_warnings.push({
                                        sanction: charge.prescribed_sanction,
                                        expiry: expiry,
                                        case: case_name
                                    });
                                }
                            }
                        });
                    }

                    pending_calls--;
                    if (pending_calls === 0) {
                        // Determine breach number from active warnings count
                        const breach_count = active_warnings.length + 1;
                        const breach_map = {1: '1st Breach', 2: '2nd Breach', 3: '3rd Breach', 4: '4th Breach'};
                        const breach_number = breach_map[breach_count] || '4th Breach';

                        set_breach_and_sanction(frm, cdt, cdn, row, breach_number);

                        if (active_warnings.length > 0) {
                            frappe.msgprint({
                                title: __('Active Prior Warnings Found'),
                                indicator: 'orange',
                                message: __(`Found ${active_warnings.length} active prior warning(s) for this employee and offence. Breach number set to <b>${breach_number}</b>.`)
                            });
                        }
                    }
                });
            });
        }
    });
}


/**
 * Once breach number is known, fetch the prescribed sanction from 
 * Offence Sanction Matrix and set fields on the child row.
 */
function set_breach_and_sanction(frm, cdt, cdn, row, breach_number) {
    frappe.model.set_value(cdt, cdn, 'breach_number', breach_number);

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Offence Sanction Matrix',
            filters: [
                ['offence', '=', row.specific_offence],
                ['breach_number', '=', breach_number]
            ],
            fields: ['prescribed_sanction'],
            limit_page_length: 1
        },
        callback(r) {
            if (r.message && r.message.length > 0) {
                const sanction = r.message[0].prescribed_sanction;
                frappe.model.set_value(cdt, cdn, 'prescribed_sanction', sanction);

                // Calculate and set warning expiry date
                set_warning_expiry(cdt, cdn, sanction);

                // Alert if Summary Dismissal
                if (sanction === 'Summary Dismissal') {
                    frappe.msgprint({
                        title: __('⚠ Summary Dismissal'),
                        indicator: 'red',
                        message: __(`The prescribed sanction for <b>${row.specific_offence}</b> (${breach_number}) is <b>Summary Dismissal</b>. This case will proceed to a Disciplinary Hearing regardless of the exculpation outcome.`)
                    });
                }
            } else {
                frappe.msgprint({
                    title: __('Sanction Not Found'),
                    indicator: 'orange',
                    message: __(`No sanction found in the matrix for <b>${row.specific_offence}</b> at <b>${breach_number}</b>. Please verify the Offence Sanction Matrix.`)
                });
            }
            frm.refresh_field('charge_description');
        }
    });
}


/**
 * Fetch prescribed sanction when breach number is manually changed.
 */
function fetch_prescribed_sanction(frm, cdt, cdn, row) {
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Offence Sanction Matrix',
            filters: [
                ['offence', '=', row.specific_offence],
                ['breach_number', '=', row.breach_number]
            ],
            fields: ['prescribed_sanction'],
            limit_page_length: 1
        },
        callback(r) {
            if (r.message && r.message.length > 0) {
                frappe.model.set_value(cdt, cdn, 'prescribed_sanction', r.message[0].prescribed_sanction);
                set_warning_expiry(cdt, cdn, r.message[0].prescribed_sanction);
                frm.refresh_field('charge_description');
            }
        }
    });
}


/**
 * Set the warning_expiry_date field based on sanction type:
 *   - Verbal Warning  → 6 months from today
 *   - Written Warning → 12 months from today
 *   - Others          → no expiry (blank)
 */
function set_warning_expiry(cdt, cdn, sanction) {
    let expiry_date = null;
    const today = frappe.datetime.get_today();

    if (sanction && sanction.toLowerCase().includes('verbal warning')) {
        expiry_date = frappe.datetime.add_months(today, 6);
    } else if (sanction && sanction.toLowerCase().includes('written warning')) {
        expiry_date = frappe.datetime.add_months(today, 12);
    } else if (sanction && sanction.toLowerCase().includes('final warning')) {
        // Final Warning — treat as 12 months for counting purposes
        expiry_date = frappe.datetime.add_months(today, 12);
    }
    // Summary Dismissal / Suspension / Demotion — no expiry needed

    frappe.model.set_value(cdt, cdn, 'warning_expiry_date', expiry_date);
}


// ============================================================
// POPULATE VERDICT TABLE (Disciplinary Hearing tab)
// ============================================================

/**
 * Copies each charge row into the Verdict child table so the
 * hearing committee can record a decision per charge.
 * Only adds rows not already present.
 */
function populate_verdict_from_charges(frm) {
    if (!frm.doc.charge_description || frm.doc.charge_description.length === 0) return;

    let existing_offences = (frm.doc.hearing_outcome || []).map(r => r.specific_offence);

    frm.doc.charge_description.forEach((charge) => {
        if (!existing_offences.includes(charge.specific_offence)) {
            let new_row = frm.add_child('hearing_outcome');
            new_row.specific_offence    = charge.specific_offence;
            new_row.description         = charge.description;
            new_row.breach_number       = charge.breach_number;
            new_row.prescribed_sanction = charge.prescribed_sanction;
            new_row.comments            = charge.comments;
            // guilty, verdict_decision and hearing_notes to be filled by committee
        }
    });

    frm.refresh_field('hearing_outcome');
}


// ============================================================
// POPULATE APPEAL VERDICT TABLE (Appeal tab)
// ============================================================

/**
 * Copies verdict rows into the Appeal Verdict table so the
 * appeal committee has the full original verdict to review.
 */
function populate_appeal_verdict_from_verdict(frm) {
    if (!frm.doc.hearing_outcome || frm.doc.hearing_outcome.length === 0) return;

    let existing = (frm.doc.appeal_verdict || []).map(r => r.specific_offence);

    frm.doc.hearing_outcome.forEach((verdict) => {
        if (!existing.includes(verdict.specific_offence)) {
            let new_row = frm.add_child('appeal_verdict');
            new_row.specific_offence        = verdict.specific_offence;
            new_row.description             = verdict.description;
            new_row.breach_number           = verdict.breach_number;
            new_row.prescribed_sanction     = verdict.prescribed_sanction;
            new_row.original_verdict        = verdict.guilty;
            new_row.original_verdict_notes  = verdict.hearing_notes || '';
            // appeal_decision and appeal_notes to be filled by appeal committee
        }
    });

    frm.refresh_field('appeal_verdict');
}


// ============================================================
// WARNING PROMPT — triggered before workflow state transition
// ============================================================

/**
 * Watches workflow_state. When the outcome involves a warning,
 * prompts the user to enter the warning text which is then saved
 * to the appropriate warning field in the Warning tab.
 */
function handle_workflow_state_change(frm) {
    const state = frm.doc.workflow_state;

    if (state === 'Verbal Warning Issued') {
        show_warning_prompt(frm, 'Verbal Warning',
            'verbal_warning',
            'Please enter the verbal warning statement to be recorded:');

    } else if (state === 'Written Warning Issued') {
        show_warning_prompt(frm, 'Written Warning',
            'warning',
            'Please enter the written warning statement to be recorded:');

    } else if (state === 'Hearing Warning Issued') {
        show_warning_prompt(frm, 'Hearing Warning',
            'hearing_warning',
            'Please enter the hearing warning statement to be recorded:');
    }

    // Auto-populate tables when entering hearing/appeal states
    if (state === 'Disciplinary Hearing') {
        populate_verdict_from_charges(frm);
    }
    if (state === 'Appeal') {
        populate_appeal_verdict_from_verdict(frm);
    }
}


/**
 * Shows a dialog prompting for warning text.
 * On confirmation, saves the text to the specified fieldname (Warning tab).
 */
function show_warning_prompt(frm, warning_type, fieldname, message_text) {
    frappe.prompt([
        {
            label: warning_type + ' Statement',
            fieldname: 'warning_text',
            fieldtype: 'Text Editor',
            reqd: 1,
            description: message_text
        }
    ],
    (values) => {
        frm.set_value(fieldname, values.warning_text);
        frappe.show_alert({
            message: __(`${warning_type} recorded in the Warning tab.`),
            indicator: 'green'
        }, 5);
        frm.save();
    },
    __(`Record ${warning_type}`),
    __('Save Warning')
    );
}


/**
 * Prompt for warning when triggered from hearing_decision field
 */
function prompt_warning_comment(frm, decision_type) {
    const fieldname = decision_type === 'Verbal Warning' ? 'verbal_warning' : 'warning';
    show_warning_prompt(frm, decision_type, fieldname,
        `A ${decision_type} has been selected as the hearing outcome. Please enter the warning statement:`);
}


