function setup_custom_buttons(frm) {
    if (frm.is_new()) return;

    const state = frm.doc.workflow_state;

    // Button to manually trigger verdict population (Hearing tab)
    if (state === 'Disciplinary Hearing') {
        frm.add_custom_button(__('Populate Verdict Table'), () => {
            populate_verdict_from_charges(frm);
            frappe.show_alert({ message: __('Verdict table populated from charges.'), indicator: 'green' }, 4);
        }, __('Actions'));
    }

    // Button to manually populate appeal verdict (Appeal tab)
    if (state === 'Appeal') {
        frm.add_custom_button(__('Populate Appeal Verdict'), () => {
            populate_appeal_verdict_from_verdict(frm);
            frappe.show_alert({ message: __('Appeal verdict table populated from hearing outcomes.'), indicator: 'green' }, 4);
        }, __('Actions'));
    }

    // View breach history button — available at any state
    if (frm.doc.employee) {
        frm.add_custom_button(__('View Breach History'), () => {
            show_breach_history(frm);
        }, __('Actions'));
    }
}


/**
 * Shows a dialog with the full breach history for this employee.
 */
function show_breach_history(frm) {
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Disciplinary',
            filters: [
                ['employee', '=', frm.doc.employee],
                ['name', '!=', frm.doc.name || '']
            ],
            fields: ['name', 'workflow_state', 'date_and_time_of_the_occurrence'],
            order_by: 'date_and_time_of_the_occurrence desc',
            limit_page_length: 100
        },
        callback(r) {
            if (!r.message || r.message.length === 0) {
                frappe.msgprint(__('No prior disciplinary cases found for this employee.'));
                return;
            }

            let table_html = `
                <table class="table table-bordered table-sm">
                    <thead>
                        <tr>
                            <th>Case</th>
                            <th>Date of Occurrence</th>
                            <th>Status</th>
                            <th>Charges</th>
                        </tr>
                    </thead>
                    <tbody>`;

            let pending = r.message.length;
            let rows_html = [];

            r.message.forEach((doc, idx) => {
                frappe.db.get_doc('Disciplinary', doc.name).then((full_doc) => {
                    let charges = (full_doc.charge_description || []).map(c =>
                        `<li>${c.specific_offence} — ${c.breach_number} — <b>${c.prescribed_sanction}</b> 
                         ${c.warning_expiry_date ? '(Expires: ' + c.warning_expiry_date + ')' : ''}</li>`
                    ).join('');

                    rows_html[idx] = `
                        <tr>
                            <td><a href="/app/disciplinary/${doc.name}" target="_blank">${doc.name}</a></td>
                            <td>${doc.date_and_time_of_the_occurrence || '-'}</td>
                            <td>${doc.workflow_state}</td>
                            <td><ul style="margin:0;padding-left:16px;">${charges}</ul></td>
                        </tr>`;

                    pending--;
                    if (pending === 0) {
                        table_html += rows_html.join('') + '</tbody></table>';
                        frappe.msgprint({
                            title: __(`Breach History — ${frm.doc.employee_name}`),
                            message: table_html,
                            wide: true
                        });
                    }
                });
            });
        }
    });
}


// ============================================================
// DOCTYPE CHILD TABLE: Verdict  (fields reference)
// ============================================================
// The 'Verdict' child doctype should have these fields:
//   specific_offence    Link  (Offence Master)  — read only
//   description         Data                    — read only
//   breach_number       Select (1st-4th)         — read only
//   prescribed_sanction Data                    — read only
//   comments            Small Text              — read only (from charge)
//   guilty              Select: Guilty / Not Guilty / Inconclusive
//   hearing_notes       Text Editor             — committee remarks
//
// ============================================================
// DOCTYPE CHILD TABLE: Appeal Verdict  (fields reference)
// ============================================================
// The 'Appeal Verdict' child doctype should have these fields:
//   specific_offence        Link (Offence Master)  — read only
//   description             Data                   — read only
//   breach_number           Select                 — read only
//   prescribed_sanction     Data                   — read only
//   original_verdict        Data (Guilty/Not Guilty/Inconclusive) — read only
