// ============================================================
// ERPNext Client Script — Disciplinary Doctype  (v2)
// ============================================================
// Changes from v1:
//   • Workflow states aligned to "Revised Disciplinary" workflow
//   • Summary Dismissal guard: forces Recommend Disciplinary Hearing
//     path regardless of exculpation outcome
//   • Stage guidance banner: contextual top-of-form instruction bar
//   • Warning prompt fieldnames updated to match new states
// ============================================================

frappe.ui.form.on('Disciplinary', {

    // ----------------------------------------------------------
    // FORM SETUP
    // ----------------------------------------------------------
    setup(frm) {
        frm.set_indicator_formatter('specific_offence', (row) => {
            return row.prescribed_sanction === 'Summary Dismissal' ? 'red' : 'green';
        });
    },

    onload(frm) {
        if (frm.doc.employee && frm.doc.charge_description) {
            frm.doc.charge_description.forEach((row) => {
                if (row.specific_offence && !row.breach_number) {
                    calculate_breach_number(frm, row);
                }
            });
        }
    },

    refresh(frm) {
        // Show contextual guidance banner for current workflow state
        show_stage_guidance(frm);

        // Setup custom action buttons
        setup_custom_buttons(frm);

        // ── Populate hearing verdict table ──────────────────────
        // NEW state name: 'Hearing Outcome' (was 'Disciplinary Hearing')
        if (frm.doc.workflow_state === 'Hearing Outcome') {
            populate_verdict_from_charges(frm);
        }

        // ── Populate appeal verdict table ───────────────────────
        // NEW state name: 'Appeal Committee' (was 'Appeal')
        if (frm.doc.workflow_state === 'Appeal Committee') {
            populate_appeal_verdict_from_verdict(frm);
        }
    },

    workflow_state(frm) {
        handle_workflow_state_change(frm);
    },

    // Exculpation outcome field handler
    select_jhxk(frm) {
        if (frm.doc.select_jhxk === 'Proceed to Hearing') {
            populate_verdict_from_charges(frm);
        }
    },

    hearing_decision(frm) {
        if (['Warning', 'Verbal Warning'].includes(frm.doc.hearing_decision)) {
            prompt_warning_comment(frm, frm.doc.hearing_decision);
        }
    }
});


// ============================================================
// DISCIPLINARY CHARGES CHILD TABLE EVENTS
// ============================================================

frappe.ui.form.on('Disciplinary Charges', {

    specific_offence(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        if (!row.specific_offence) return;

        frappe.db.get_value('Offence Master', row.specific_offence,
            ['definition', 'offence_code', 'offence_category'], (r) => {

            if (r) {
                frappe.model.set_value(cdt, cdn, 'description', r.definition || '');
            }
            calculate_breach_number(frm, row, cdt, cdn);
        });
    },

    breach_number(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        if (row.specific_offence && row.breach_number) {
            fetch_prescribed_sanction(frm, cdt, cdn, row);
        }
    }
});


// ============================================================
// VERDICT CHILD TABLE EVENTS
// ============================================================

frappe.ui.form.on('Verdict', {
    guilty(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        if (row.prescribed_sanction === 'Summary Dismissal' && row.guilty === 'Not Guilty') {
            frappe.msgprint({
                title: __('Notice'),
                indicator: 'orange',
                message: __('This charge carries a Summary Dismissal sanction. Even with a Not Guilty finding, the matter must still proceed through the hearing process and a verdict must be formally recorded.')
            });
        }
    }
});


