function show_breach_history(frm) {
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype:    'Disciplinary',
            filters:    [
                ['employee', '=', frm.doc.employee],
                ['name',     '!=', frm.doc.name || '']
            ],
            fields:     ['name', 'workflow_state', 'date_and_time_of_the_occurrence'],
            order_by:   'date_and_time_of_the_occurrence desc',
            limit_page_length: 100
        },
        callback(r) {
            if (!r.message || r.message.length === 0) {
                frappe.msgprint(__('No prior disciplinary cases found for this employee.'));
                return;
            }

            let table_html = `
                <table class="table table-bordered table-sm">
                    <thead>
                        <tr>
                            <th>Case</th>
                            <th>Date of Occurrence</th>
                            <th>Status</th>
                            <th>Charges</th>
                        </tr>
                    </thead>
                    <tbody>`;

            let pending   = r.message.length;
            let rows_html = [];

            r.message.forEach((doc, idx) => {
                frappe.db.get_doc('Disciplinary', doc.name).then((full_doc) => {
                    let charges = (full_doc.charge_description || []).map(c =>
                        `<li>${c.specific_offence} — ${c.breach_number} — <b>${c.prescribed_sanction}</b> 
                         ${c.warning_expiry_date ? '(Expires: ' + c.warning_expiry_date + ')' : ''}</li>`
                    ).join('');

                    rows_html[idx] = `
                        <tr>
                            <td><a href="/app/disciplinary/${doc.name}" target="_blank">${doc.name}</a></td>
                            <td>${doc.date_and_time_of_the_occurrence || '-'}</td>
                            <td>${doc.workflow_state}</td>
                            <td><ul style="margin:0;padding-left:16px;">${charges}</ul></td>
                        </tr>`;

                    pending--;
                    if (pending === 0) {
                        table_html += rows_html.join('') + '</tbody></table>';
                        frappe.msgprint({
                            title:   __(`Breach History — ${frm.doc.employee_name}`),
                            message: table_html,
                            wide:    true
                        });
                    }
                });
            });
        }
    });
}

// ============================================================
// ERPNext Client Script — Disciplinary Doctype  (v3)
// ============================================================
// Changes from v2:
//   • Clarified auto-populate timing (documented below)
//   • Warning dialogue fires on "Issue Warning" workflow action
//     AND when CEO rejects at "Pending CEO Approval" — text is
//     saved into the Warning tab fields
//   • Summary Dismissal end-state action buttons:
//       – Create Employee Separation
//       – Trigger Forced Leave
//     These appear when the final outcome is Summary Dismissal
//     (Outcome Evaluation / Case Closed stages)
//   • Workflow condition safe_exec fix — replaced unsupported
//     generator expression with a whitelisted server method
// ============================================================
//
// AUTO-POPULATE TIMING (answers your question):
// ─────────────────────────────────────────────
//  Hearing Outcome table  → populated automatically when:
//    a) frm.refresh() fires and workflow_state === 'Hearing Outcome'
//    b) workflow_state field changes to 'Hearing Outcome'
//    c) select_jhxk (exculpation outcome) is set to 'Proceed to Hearing'
//    d) Supervisor clicks the manual "Populate Verdict Table" button
//
//  Appeal Verdict table   → populated automatically when:
//    a) frm.refresh() fires and workflow_state === 'Appeal Committee'
//    b) workflow_state field changes to 'Appeal Committee'
//    c) Supervisor clicks the manual "Populate Appeal Verdict" button
//
// ============================================================
//
// SAFE_EXEC WORKFLOW CONDITION FIX:
// ───────────────────────────────────
//  ERPNext's safe_eval does NOT support generator expressions or
//  the built-in `any()` function. Use one of these alternatives:
//
//  Option A — Server Whitelisted Method (RECOMMENDED):
//    Add a Python method in your app (see bottom of this file)
//    and call it in the workflow transition condition field as:
//      doc.has_summary_dismissal_charge()
//    after adding it as a document method.
//
//  Option B — Simple field flag (SIMPLEST):
//    Add a checkbox field "has_summary_dismissal" (Int/Check) to
//    the Disciplinary doctype. Set it via the client script when
//    a Summary Dismissal charge is added. Then the workflow
//    condition is simply:
//      doc.has_summary_dismissal == 0
//    (blocks "close" path; allows it only when flag is 0)
//    This is the most reliable approach — see the helper below.
//
// ============================================================

frappe.ui.form.on('Disciplinary', {

    // ----------------------------------------------------------
    // FORM SETUP
    // ----------------------------------------------------------
    setup(frm) {
        frm.set_indicator_formatter('specific_offence', (row) => {
            return row.prescribed_sanction === 'Summary Dismissal' ? 'red' : 'green';
        });
    },

    onload(frm) {
        if (frm.doc.employee && frm.doc.charge_description) {
            frm.doc.charge_description.forEach((row) => {
                if (row.specific_offence && !row.breach_number) {
                    calculate_breach_number(frm, row);
                }
            });
        }
    },

    refresh(frm) {
        // Show contextual guidance banner for current workflow state
        show_stage_guidance(frm);

        // Setup all custom action buttons
        setup_custom_buttons(frm);

        // ── Auto-populate hearing verdict table ─────────────────
        // Fires on every refresh when in Hearing Outcome state so
        // newly added charges are always reflected in the table.
        if (frm.doc.workflow_state === 'Hearing Outcome') {
            populate_verdict_from_charges(frm);
        }

        // ── Auto-populate appeal verdict table ─────────────────
        // Fires on every refresh when in Appeal Committee state.
        if (frm.doc.workflow_state === 'Appeal Committee') {
            populate_appeal_verdict_from_verdict(frm);
        }
    },

    workflow_state(frm) {
        handle_workflow_state_change(frm);
    },

    // Exculpation outcome field handler
    select_jhxk(frm) {
        if (frm.doc.select_jhxk === 'Unsatisfactory Proceed to Hearing') {
            populate_verdict_from_charges(frm);
        }
    },

    hearing_decision(frm) {
        if (['Warning', 'Verbal Warning'].includes(frm.doc.hearing_decision)) {
            prompt_warning_comment(frm, frm.doc.hearing_decision);
        }
    }
});


