// ============================================================
// SUMMARY DISMISSAL END-STATE ACTION BUTTONS
// ============================================================
// These appear when the final outcome is Summary Dismissal and
// the case is at Outcome Evaluation (employee accepted) or
// Case Closed. They allow:
//   1. Creating an Employee Separation record automatically
//   2. Triggering a Forced Leave record

function outcome_is_summary_dismissal(frm) {
    // Check hearing outcome verdicts for Summary Dismissal sanction
    // where the finding was Guilty
    return (frm.doc.hearing_outcome || []).some(
        row => row.prescribed_sanction === 'Summary Dismissal' && row.guilty === 'Guilty'
    );
}

/**
 * Creates an Employee Separation document pre-filled with the
 * employee's details and the reason set to Dismissal.
 */
function create_employee_separation(frm) {
    frappe.confirm(
        `This will create an <b>Employee Separation</b> record for ` +
        `<b>${frm.doc.employee_name || frm.doc.employee}</b> with reason <b>Dismissal</b>. Proceed?`,
        () => {
            frappe.call({
                method: 'frappe.client.insert',
                args: {
                    doc: {
                        doctype:              'Employee Separation',
                        employee:             frm.doc.employee,
                        employee_name:        frm.doc.employee_name,
                        department:           frm.doc.department,
                        designation:          frm.doc.designation,
                        // Standard ERPNext field for reason
                        reason_for_resignation: 'Termination',
                        // Link back to this disciplinary case
                        // (add a custom Link field 'disciplinary_case' on Employee Separation if needed)
                        // disciplinary_case: frm.doc.name,
                    }
                },
                callback(r) {
                    if (r.message) {
                        frappe.show_alert({
                            message: __(`Employee Separation <b>${r.message.name}</b> created successfully.`),
                            indicator: 'green'
                        }, 8);
                        // Open the newly created record in a new tab
                        window.open(`/app/employee-separation/${r.message.name}`, '_blank');
