                        if (frm.fields_dict['employee_separation']) {
                            frm.set_value('employee_separation', r.message.name);
                            frm.save();
                        }
                    }
                }
            });
        }
    );
}

/**
 * Creates a Forced Leave document for the employee.
 * Assumes a DocType called "Forced Leave" exists with at minimum:
 *   employee, employee_name, from_date, reason, disciplinary_case fields.
 * Adjust field names to match your actual Forced Leave doctype.
 */
function trigger_forced_leave(frm) {
    frappe.prompt([
        {
            label: 'From Date',
            fieldname: 'from_date',
            fieldtype: 'Date',
            reqd: 1,
            default: frappe.datetime.get_today()
        },
        {
            label: 'To Date (if known)',
            fieldname: 'to_date',
            fieldtype: 'Date'
        },
        {
            label: 'Reason / Notes',
            fieldname: 'reason',
            fieldtype: 'Small Text',
            reqd: 1,
            default: `Pending Summary Dismissal — Disciplinary Case ${frm.doc.name}`
        }
    ],
    (values) => {
        frappe.call({
            method: 'frappe.client.insert',
            args: {
                doc: {
                    doctype:           'Forced Leave',
                    employee:          frm.doc.employee,
                    employee_name:     frm.doc.employee_name,
                    department:        frm.doc.department,
                    from_date:         values.from_date,
                    to_date:           values.to_date || null,
                    reason:            values.reason,
                    disciplinary_case: frm.doc.name
                }
            },
            callback(r) {
                if (r.message) {
                    frappe.show_alert({
                        message: __(`Forced Leave <b>${r.message.name}</b> created successfully.`),
                        indicator: 'green'
                    }, 8);
                    window.open(`/app/forced-leave/${r.message.name}`, '_blank');
                }
            }
        });
    },
    __('Create Forced Leave Record'),
    __('Create')
    );
}


