// CUSTOM BUTTONS
// ============================================================

function setup_custom_buttons(frm) {
    if (frm.is_new()) return;

    const state = frm.doc.workflow_state;

    // ── Populate verdict table (Hearing Outcome) ─────────────────
    if (state === 'Hearing Outcome') {
        frm.add_custom_button(__('Populate Verdict Table'), () => {
            populate_verdict_from_charges(frm);
            frappe.show_alert({ message: __('Verdict table populated from charges.'), indicator: 'green' }, 4);
        }, __('Actions'));
    }

    // ── Populate appeal verdict (Appeal Committee) ───────────────
    if (state === 'Appeal Committee') {
        frm.add_custom_button(__('Populate Appeal Verdict'), () => {
            populate_appeal_verdict_from_verdict(frm);
            frappe.show_alert({ message: __('Appeal verdict table populated from hearing outcomes.'), indicator: 'green' }, 4);
        }, __('Actions'));
    }

    // ── CEO Reject — record rejection reason ─────────────────────
    // Appears when CEO is reviewing the hearing outcome.
    // Click BEFORE clicking the "Reject" workflow action button.
    if (state === 'Pending CEO Approval') {
        frm.add_custom_button(__('Record Rejection Reason'), () => {
            show_ceo_rejection_prompt(frm);
        }, __('Actions'));
    }

    // ── Summary Dismissal end-state buttons ──────────────────────
    // Shown when outcome is Summary Dismissal and employee has
    // either accepted the verdict or the case is closed.
    const sd_states = ['Outcome Evaluation', 'Case Closed'];
    if (sd_states.includes(state) && outcome_is_summary_dismissal(frm)) {
        frm.add_custom_button(__('Create Employee Separation'), () => {
            create_employee_separation(frm);
        }, __('Summary Dismissal Actions'));

        frm.add_custom_button(__('Trigger Forced Leave'), () => {
            trigger_forced_leave(frm);
        }, __('Summary Dismissal Actions'));
    }

    // ── View breach history ──────────────────────────────────────
    if (frm.doc.employee) {
        frm.add_custom_button(__('View Breach History'), () => {
            show_breach_history(frm);
        }, __('Actions'));
    }

    // ── Print case summary ───────────────────────────────────────
    if (state !== 'Draft') {
        frm.add_custom_button(__('Print Case Summary'), () => {
            const url = `/printview?doctype=Disciplinary&name=${frm.doc.name}&format=Disciplinary Case Summary&no_letterhead=0`;
            window.open(url, '_blank');
        }, __('Actions'));
    }
}


// ============================================================
// BREACH HISTORY DIALOG
// ============================================================

function show_breach_history(frm) {
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Disciplinary',
            filters: [['employee', '=', frm.doc.employee], ['name', '!=', frm.doc.name || '']],
            fields: ['name', 'workflow_state', 'date_and_time_of_the_occurrence'],
            order_by: 'date_and_time_of_the_occurrence desc',
            limit_page_length: 100
        },
        callback(r) {
            if (!r.message || r.message.length === 0) {
                frappe.msgprint(__('No prior disciplinary cases found for this employee.'));
                return;
            }

            let table_html = `<table class="table table-bordered table-sm">
                <thead><tr><th>Case</th><th>Date of Occurrence</th><th>Status</th><th>Charges</th></tr></thead>
                <tbody>`;

            let pending   = r.message.length;
            let rows_html = [];

            r.message.forEach((doc, idx) => {
                frappe.db.get_doc('Disciplinary', doc.name).then((full_doc) => {
                    const charges = (full_doc.charge_description || []).map(c =>
                        `<li>${c.specific_offence} — ${c.breach_number} — <b>${c.prescribed_sanction}</b>` +
                        `${c.warning_expiry_date ? ' (Expires: ' + c.warning_expiry_date + ')' : ''}</li>`
                    ).join('');

                    rows_html[idx] = `<tr>
                        <td><a href="/app/disciplinary/${doc.name}" target="_blank">${doc.name}</a></td>
                        <td>${doc.date_and_time_of_the_occurrence || '-'}</td>
                        <td>${doc.workflow_state}</td>
                        <td><ul style="margin:0;padding-left:16px;">${charges}</ul></td>
                    </tr>`;

                    pending--;
                    if (pending === 0) {
                        table_html += rows_html.join('') + '</tbody></table>';
                        frappe.msgprint({
                            title: __(`Breach History — ${frm.doc.employee_name}`),
                            message: table_html,
                            wide: true
                        });
                    }
                });
            });
        }
    });
}

