// ================================================================
// CLIENT SCRIPT — Disciplinary Doctype
// Purpose: Show a guidance banner at the top of the form telling
// the current user exactly what they need to do at each workflow
// state. Nothing else — no field locking (handled by server script).
// ================================================================


// ----------------------------------------------------------------
// ENTRY POINT
// frappe.ui.form.on listens for events on the Disciplinary doctype.
// We hook into three events so the banner always shows:
//   refresh        — fires every time the form loads or reloads
//   onload         — fires when the form first opens
//   workflow_state — fires when the workflow state changes
// ----------------------------------------------------------------
frappe.ui.form.on("Disciplinary", {

    refresh: function(frm) {
        show_stage_guidance(frm);
    },

    onload: function(frm) {
        show_stage_guidance(frm);
    },

    workflow_state: function(frm) {
        show_stage_guidance(frm);
    }

});


// ----------------------------------------------------------------
// MAIN FUNCTION — show_stage_guidance(frm)
// Reads the current workflow_state, looks it up in the guidance
// map, and renders a coloured banner at the top of the form.
// ----------------------------------------------------------------
function show_stage_guidance(frm) {

    // Clear any existing banner first so we don't stack banners
    frm.dashboard.clear_headline();

    // Don't show a banner on a brand new unsaved document
    if (frm.is_new()) return;

    // Read the current state and employee name from the document
    var state    = frm.doc.workflow_state;
    var employee = frm.doc.employee_name || frm.doc.employee || "the employee";

    // ----------------------------------------------------------------
    // GUIDANCE MAP
    // Each key is an exact workflow state name (must match ERPNext).
    // Each value has:
    //   color — banner colour (blue/yellow/orange/red/green/grey)
    //   role  — shown as a badge so the user knows who should act
    //   title — bold heading of the banner
    //   body  — detailed instructions shown below the heading
    //
    // IMPORTANT: All multi-line body strings use explicit \n escape
    // sequences and standard ASCII apostrophes only. No template
    // literals, no Unicode line breaks, no curly quotes — ERPNext
    // evaluates this via new Function() which rejects those tokens.
    // ----------------------------------------------------------------
    var guidance = {

        "Draft": {
            color: "grey",
            role:  "Supervisor",
            title: "Draft — complete the incident details",
            body:  "Fill in all fields: employee details, date of occurrence, and a full " +
                   "description of the alleged offence. When ready click Submit " +
                   "to move the case to the Charge stage."
        },

        "Charge": {
            color: "blue",
            role:  "Supervisor",
            title: "Action required — Supervisor",
            body:  "Review the incident for " + employee + " and complete the Charge tab. " +
                   "Fill in Issued By, the charge description table, and indicate if this is a Summary Dismissal.\n\n" +
                   "Click Recommend Charge to send to HR Manager for review, or " +
                   "Issue Warning to close with a warning if no formal charge is needed.\n\n" +
                   "Note: If any offence carries a Summary Dismissal sanction the case must proceed to a Hearing."
        },

        "Recommendation of Charge": {
            color: "yellow",
            role:  "HR Manager",
            title: "Action required — HR Manager",
            body:  "A charge has been prepared by the Supervisor for " + employee + ". " +
                   "Review the charge details in the Charge tab.\n\n" +
                   "Click Approve Charge to pass it back to the Supervisor to formally issue, or " +
                   "Return for Revision to send it back with comments."
        },

        "Issue Charge": {
            color: "blue",
            role:  "Supervisor",
            title: "Action required — Supervisor — issue the charge",
            body:  "The charge for " + employee + " has been approved by HR Manager. " +
                   "Confirm the charge details are final then click Issue Charge.\n\n" +
                   "The system will automatically:\n" +
                   "  - Calculate the response deadline (5 working days, no weekends)\n" +
                   "  - Generate and attach a charge letter\n" +
                   "  - Email the charge letter to the employee"
        },

        "Awaiting Exculpation": {
            color: "blue",
            role:  "Employee",
            title: "Action required — Employee — submit your response",
            body:  "You have been issued a formal charge. Read the charge letter carefully.\n\n" +
                   "Go to the Exculpation tab and:\n" +
                   "  - Attach any supporting documents in Response Document\n" +
                   "  - Write your full response in Employee Response\n\n" +
                   "You must respond by the response deadline shown in the Charge tab. " +
                   "You will receive daily reminder emails until your response is submitted."
        },

        "Exculpation Evaluation": {
            color: "yellow",
            role:  "Supervisor",
            title: "Action required — Supervisor — evaluate the response",
            body:  employee + " has submitted their response. Review it in the Exculpation tab.\n\n" +
                   "Select an outcome from the Select Outcome field:\n" +
                   "  - Satisfactory — proceed to Issue Warning to close the case\n" +
                   "  - Non-Satisfactory — recommend a Disciplinary Hearing\n" +
                   "  - Dismissible — recommend a Disciplinary Hearing\n\n" +
                   "Note: If any charge carries Summary Dismissal a hearing is mandatory."
        },

        "Issue Warning": {
            color: "orange",
            role:  "Supervisor",
            title: "Action required — Supervisor — issue the warning",
            body:  "The exculpation was satisfactory. Go to the Warning tab and write the " +
                   "formal warning statement in the Warning field. " +
                   "This will be permanently recorded against " + employee + ".\n\n" +
                   "When done click Issue Warning to close the case."
        },

        "Recommend Disciplinary Hearing": {
            color: "orange",
            role:  "Director HRA",
            title: "Action required — Director HRA",
            body:  "A Disciplinary Hearing has been recommended for " + employee + ". " +
                   "Go to the Hearing tab and populate the Disciplinary Hearing Committee table " +
                   "with proposed members.\n\n" +
                   "When done click Submit to forward to the CEO for committee appointment."
        },

        "Disciplinary Committee": {
            color: "orange",
            role:  "CEO",
            title: "Action required — CEO — appoint the committee",
            body:  "A Disciplinary Hearing committee has been recommended for " + employee + ". " +
                   "Review the proposed members in the Hearing tab and adjust if needed.\n\n" +
                   "When satisfied click Committee Appointed to confirm and move to hearing scheduling."
        },

        "Set Hearing Date": {
            color: "orange",
            role:  "HRO Welfare",
            title: "Action required — HRO Welfare — set the hearing date",
            body:  "The committee has been appointed for " + employee + ". " +
                   "Set the Hearing Date in the Set Hearing Date section.\n\n" +
                   "Once saved click Invite Committee. The system will automatically:\n" +
                   "  - Email all committee members their hearing invitation\n" +
                   "  - Grant committee members read-only access to this case"
        },

        "Hearing Outcome": {
            color: "red",
            role:  "HRO Welfare",
            title: "Action required — HRO Welfare — record the hearing outcome",
            body:  "The hearing for " + employee + " has been held. " +
                   "Record the findings in the Hearing Outcome tab:\n" +
                   "  - Select the Hearing Decision\n" +
                   "  - Complete the Hearing Outcome table with a verdict per charge\n" +
                   "  - Write the Hearing Summary\n" +
                   "  - Attach the Hearing Report\n\n" +
                   "When complete click Submit for CEO Approval."
        },

        "Pending CEO Approval": {
            color: "orange",
            role:  "CEO",
            title: "Action required — Chief Executive Officer",
            body:  "This case for " + employee + " requires your approval before proceeding. " +
                   "Review the full case including the charge, response, and recommended outcome.\n\n" +
                   "  - Click Approve to proceed — the employee will be notified\n" +
                   "  - Click Reject to return the outcome to HRO Welfare for revision"
        },

        "Awaiting Employee Decision": {
            color: "blue",
            role:  "Employee",
            title: "Action required — Employee — accept or appeal the outcome",
            body:  "The disciplinary outcome for your case has been approved by the CEO. " +
                   "Review the outcome in the Hearing Outcome tab.\n\n" +
                   "  - Click Accept Verdict — accept the outcome and the case will close\n" +
                   "  - Click Appeal Verdict — appeal and the case proceeds to the appeal process\n\n" +
                   "You must respond within the stipulated timeframe."
        },

        "Grounds for Appeal": {
            color: "blue",
            role:  "Employee",
            title: "Action required — Employee — submit grounds for appeal",
            body:  "You have elected to appeal the hearing outcome. " +
                   "Go to the Appeal tab and write your full Grounds for Appeal. " +
                   "Be specific about which findings you are challenging and why.\n\n" +
                   "When done click Submit Appeal."
        },

        "Appeal Under Review": {
            color: "yellow",
            role:  "Director HRA",
            title: "Action required — Director HRA — review the appeal",
            body:  employee + " has submitted grounds for appeal. " +
                   "Review the grounds alongside the full case history.\n\n" +
                   "  - Click Approve to allow the appeal to proceed to the CEO\n" +
                   "  - Click Reject to dismiss the appeal — the original verdict stands and the case closes"
        },

        "Appeal Requested": {
            color: "orange",
            role:  "CEO",
            title: "Action required — CEO — appoint the appeal committee",
            body:  "The appeal for " + employee + " has been approved. " +
                   "Go to the Appeal tab and populate the appeal committee table with members.\n\n" +
                   "When ready click Approve (Committee Appointed) to proceed to scheduling."
        },

        "Set Appeal Date": {
            color: "orange",
            role:  "HRO Welfare",
            title: "Action required — HRO Welfare — set the appeal date",
            body:  "The Appeal Committee has been appointed for " + employee + ". " +
                   "Set the Appeal Date in the Set Appeal Date section.\n\n" +
                   "Once saved click Invite Committee. The system will automatically notify all " +
                   "appeal committee members and grant them read-only access to this case."
        },

        "Appeal Outcome": {
            color: "red",
            role:  "HRO Welfare",
            title: "Action required — HRO Welfare — record the appeal outcome",
            body:  "The appeal hearing for " + employee + " has been held. " +
                   "Record the decision in the Appeal Outcome tab:\n" +
                   "  - Complete the Appeal Verdict table (Uphold / Overturn / Vary per charge)\n" +
                   "  - Select the Appeal Decision\n" +
                   "  - Attach the Appeal Hearing Report\n" +
                   "  - Write the Final Remarks\n\n" +
                   "When complete click Submit for Approval."
        },

        "Pending Outcome Approval": {
            color: "orange",
            role:  "CEO",
            title: "Action required — CEO — approve the appeal outcome",
            body:  "The appeal outcome for " + employee + " is ready for final approval. " +
                   "Review the appeal verdict and final remarks in the Appeal Outcome tab.\n\n" +
                   "Click Close Case to formally close this matter."
        },

        "Case Closed": {
            color: "green",
            role:  "All",
            title: "Case closed",
            body:  "This disciplinary case for " + employee + " has been formally closed. " +
                   "All records are now read-only. " +
                   "The Case Summary tab provides a full overview of the case history."
        }

    };


    // ----------------------------------------------------------------
    // LOOK UP THE CURRENT STATE
    // If the state is not in our map we exit quietly — no banner is
    // better than a broken banner.
    // ----------------------------------------------------------------
    var info = guidance[state];
    if (!info) return;


    // ----------------------------------------------------------------
    // COLOUR MAPS
    // Maps colour names to hex values for background and border.
    // ----------------------------------------------------------------
    var bg_color = {
        blue:   "#d4e6f1",
        yellow: "#fef9e7",
        orange: "#fdebd0",
        red:    "#fadbd8",
        green:  "#d5f5e3",
        grey:   "#f0f0f0"
    };

    var border_color = {
        blue:   "#2980b9",
        yellow: "#f39c12",
        orange: "#e67e22",
        red:    "#c0392b",
        green:  "#27ae60",
        grey:   "#bdc3c7"
    };


    // ----------------------------------------------------------------
    // ROLE BADGE
    // Small pill shown next to the title so the user knows immediately
    // if this action is meant for them or someone else.
    // ----------------------------------------------------------------
    var badge =
        '<span style="' +
            'display:inline-block;' +
            'margin-left:10px;' +
            'padding:2px 10px;' +
            'border-radius:12px;' +
            'background:' + border_color[info.color] + ';' +
            'color:#fff;' +
            'font-size:11px;' +
            'font-weight:600;' +
            'vertical-align:middle;' +
        '">' + info.role + '</span>';


    // ----------------------------------------------------------------
    // BUILD THE BANNER HTML
    // body text uses \n converted to <br> so line breaks render in HTML.
    // ----------------------------------------------------------------
    var body_html = info.body.replace(/\n/g, "<br>");

    var banner =
        '<div style="' +
            'border-left:4px solid ' + border_color[info.color] + ';' +
            'background:' + bg_color[info.color] + ';' +
            'padding:10px 14px;' +
            'border-radius:4px;' +
            'margin-bottom:6px;' +
        '">' +
            '<div style="font-weight:700;font-size:13px;margin-bottom:6px;">' +
                info.title + badge +
            '</div>' +
            '<div style="font-size:12px;line-height:1.6;">' + body_html + '</div>' +
        '</div>';


    // ----------------------------------------------------------------
    // RENDER THE BANNER
    // set_headline_alert pushes HTML into the form dashboard area
    // above all the fields.
    // ----------------------------------------------------------------
    frm.dashboard.set_headline_alert(banner, info.color);

}

