// ================================================================
// FIELD PERMISSION FUNCTION
// Sets every managed field read-only, then re-enables only the
// fields allowed in the current state.
// ================================================================
function apply_field_permissions(frm) {
    var state = frm.doc.workflow_state;

    // Lock everything first
    ALL_MANAGED_FIELDS.forEach(function(fname) {
        frm.set_df_property(fname, "read_only", 1);
    });

    // Case Closed — everything stays locked, nothing more to do
    if (state === "Case Closed") {
        frm.refresh_fields();
        return;
    }

    // Unlock only the fields allowed in this state
    var allowed = STATE_FIELDS[state] || [];
    allowed.forEach(function(fname) {
        frm.set_df_property(fname, "read_only", 0);
    });

    frm.refresh_fields();
}


// ================================================================
// CASE SUMMARY — render a read-only timeline in the Case Summary tab
// ================================================================
function render_case_summary(frm) {
    if (frm.is_new()) return;

    // States in workflow order for the timeline
    var ORDERED_STATES = [
        "Draft",
        "Charge",
        "Recommendation of Charge",
        "Issue Charge",
        "Awaiting Exculpation",
        "Exculpation Evaluation",
        "Issue Warning",
        "Recommend Disciplinary Hearing",
        "Disciplinary Committee",
        "Set Hearing Date",
        "Hearing Outcome",
        "Pending CEO Approval",
        "Awaiting Employee Decision",
        "Grounds for Appeal",
        "Appeal Under Review",
        "Appeal Requested",
        "Set Appeal Date",
        "Appeal Outcome",
        "Pending Outcome Approval",
        "Case Closed"
    ];

    var current = frm.doc.workflow_state;
    var current_idx = ORDERED_STATES.indexOf(current);

    // Build a simple snapshot of key case data for the summary
    var d = frm.doc;

    var rows = [
        ["Employee",           d.employee_name || d.employee || "—"],
        ["Department",         d.department || "—"],
        ["Date of Occurrence", d.date_and_time_of_the_occurrence || "—"],
        ["Supervisor",         d.name_of_charging_officer || d.supervisor || "—"],
        ["Current State",      "<b>" + current + "</b>"],
        ["Response Deadline",  d.response_deadline || "—"],
        ["Hearing Date",       d.hearing_date || "—"],
        ["Hearing Decision",   d.hearing_decision || "—"],
        ["Select Outcome",     d.select_outcome || "—"],
        ["Appeal Decision",    d.appeal_decision || "—"],
    ];

    var table_rows = rows.map(function(r) {
        return "<tr>" +
            "<td style='padding:5px 10px;font-weight:600;white-space:nowrap;" +
                "border-bottom:1px solid #eee;width:200px;'>" + r[0] + "</td>" +
            "<td style='padding:5px 10px;border-bottom:1px solid #eee;'>" + r[1] + "</td>" +
            "</tr>";
    }).join("");

    // Build state timeline pills
    var pills = ORDERED_STATES.map(function(s, i) {
        var done    = i < current_idx;
        var active  = i === current_idx;
        var bg      = active ? "#2980b9" : (done ? "#27ae60" : "#ecf0f1");
        var color   = (active || done) ? "#fff" : "#7f8c8d";
        var weight  = active ? "700" : "400";
        return "<span style='" +
            "display:inline-block;" +
            "margin:3px 4px;" +
            "padding:4px 12px;" +
            "border-radius:12px;" +
            "background:" + bg + ";" +
            "color:" + color + ";" +
            "font-size:11px;" +
            "font-weight:" + weight + ";" +
        "'>" + s + "</span>";
    }).join("");

    var html =
        "<div style='padding:16px;'>" +
            "<h4 style='margin-bottom:12px;font-size:14px;color:#2c3e50;'>Case Overview</h4>" +
            "<table style='border-collapse:collapse;width:100%;margin-bottom:20px;'>" +
                table_rows +
            "</table>" +
            "<h4 style='margin-bottom:10px;font-size:14px;color:#2c3e50;'>Workflow Progress</h4>" +
            "<div style='line-height:2;'>" + pills + "</div>" +
        "</div>";

    // Render into the case_summary_tab using a custom HTML field or wrapper
    // ERPNext: set content on a named HTML field in that tab, or use
    // frm.fields_dict if you have an HTML fieldname there.
    // If you have an HTML field called "case_summary_html" in the tab:
    if (frm.fields_dict["case_summary_html"]) {
        frm.fields_dict["case_summary_html"].$wrapper.html(html);
    }
    // Fallback: inject into the tab section wrapper by tab fieldname
    else {
        var tab_wrapper = frm.get_field("case_summary_tab");
        if (tab_wrapper && tab_wrapper.$wrapper) {
            tab_wrapper.$wrapper.find(".frappe-tab-content").html(html);
        }
    }
}


