frappe.ui.form.on('Disciplinary', {
    validate: function(frm) {
        let state = frm.doc.workflow_state;
        let action = frm.doc.workflow_action;
        let errors = [];

        // Only validate when a workflow action is being triggered
        // Plain saves (no workflow_action) should pass through freely
        if (!action) return;

        // ─── Draft ────────────────────────────────────────────────────────
        if (state === 'Draft') {
            if (!frm.doc.employee)
                errors.push('Employee');
            if (!frm.doc.employee_name)
                errors.push('Employee Name');
            if (!frm.doc.department)
                errors.push('Department');
            if (!frm.doc.designation)
                errors.push('Job Title');
            if (!frm.doc.supervisor)
                errors.push('Supervisor');
            if (!frm.doc.name_of_charging_officer)
                errors.push('Supervisor Name');
            if (!frm.doc.date_and_time_of_the_occurrence)
                errors.push('Date of the Occurrence');
            if (!frm.doc.summary_of_issue)
                errors.push('Description of Alleged Offence');
        }

        // ─── Charge / Recommendation of Charge / Issue Charge ─────────────
        if (['Charge', 'Recommendation of Charge', 'Issue Charge'].includes(state)) {
            if (!frm.doc.issued_by)
                errors.push('Issued By');
            if (!frm.doc.charge_description || frm.doc.charge_description.length === 0)
                errors.push('Charge Description (at least one charge must be added)');
            if (!frm.doc.charge_letter)
                errors.push('Charge Letter (attachment required)');
        }

        // ─── Awaiting Exculpation ──────────────────────────────────────────
        if (state === 'Awaiting Exculpation') {
            if (!frm.doc.response_deadline)
                errors.push('Response Deadline');
        }

        // ─── Exculpation Evaluation ────────────────────────────────────────
        if (state === 'Exculpation Evaluation') {
            if (!frm.doc.employee_response)
                errors.push('Employee Response');
            if (!frm.doc.select_outcome)
                errors.push('Outcome Selection');
        }

        // ─── Issue Warning ─────────────────────────────────────────────────
        if (state === 'Issue Warning') {
            if (!frm.doc.warning)
                errors.push('Warning to Employee');
        }

        // ─── Recommend Disciplinary Hearing ────────────────────────────────
        if (state === 'Recommend Disciplinary Hearing') {
            if (!frm.doc.hearing || frm.doc.hearing.length === 0)
                errors.push('Disciplinary Hearing Committee (at least one member required)');
        }

        // ─── Disciplinary Committee ────────────────────────────────────────
        if (state === 'Disciplinary Committee') {
            if (!frm.doc.hearing || frm.doc.hearing.length === 0)
                errors.push('Disciplinary Hearing Committee (at least one member required)');
        }

        // ─── Set Hearing Date ──────────────────────────────────────────────
        if (state === 'Set Hearing Date') {
            if (!frm.doc.hearing_date)
                errors.push('Hearing Date');
            if (!frm.doc.hearing_venue)
                errors.push('Hearing Venue');
            if (!frm.doc.hearing_time)
                errors.push('Hearing Time');
        }

        // ─── Hearing Outcome ───────────────────────────────────────────────
        if (state === 'Hearing Outcome') {
            if (!frm.doc.hearing_decision)
                errors.push('Hearing Decision');
            if (!frm.doc.hearing_outcome || frm.doc.hearing_outcome.length === 0)
                errors.push('Hearing Outcome (table must be filled)');
            if (!frm.doc.hearing_summary)
                errors.push('Hearing Summary');
            if (!frm.doc.hearing_report)
                errors.push('Hearing Report (attachment required)');
        }

        // ─── Grounds for Appeal ────────────────────────────────────────────
        if (state === 'Grounds for Appeal') {
            if (!frm.doc.grounds_for_appeal)
                errors.push('Grounds for Appeal');
        }

        // ─── Set Appeal Date ───────────────────────────────────────────────
        if (state === 'Set Appeal Date') {
            if (!frm.doc.appeal_date)
                errors.push('Appeal Date');
            if (!frm.doc.appeal_time)
                errors.push('Appeal Time');
            if (!frm.doc.appeal_venue)
                errors.push('Appeal Venue');
        }

        // ─── Appeal Outcome ────────────────────────────────────────────────
        if (state === 'Appeal Outcome') {
            if (!frm.doc.appeal_verdict || frm.doc.appeal_verdict.length === 0)
                errors.push('Appeal Verdict (table must be filled)');
            if (!frm.doc.appeal_decision)
                errors.push('Appeal Decision');
            if (!frm.doc.appeal_hearing_report)
                errors.push('Appeal Hearing Report (attachment required)');
            if (!frm.doc.final_remarks)
                errors.push('Final Remarks');
        }

        // ─── Show all errors at once ───────────────────────────────────────
        if (errors.length > 0) {
            frappe.msgprint({
                title: __('Required Fields Missing'),
                indicator: 'red',
                message: __('The following fields are required before proceeding from <strong>{0}</strong>:<br><br>',
                    [state]) + errors.map(e => `• ${e}`).join('<br>')
            });
            frappe.validated = false;
        }
    }
});

