// ============================================================
// HALF PAY BUTTON
// ============================================================
// Fetches the employee's current active Salary Structure Assignment,
// reads the base amount, halves it, and creates a new assignment
// with the half-pay base. The from_date defaults to today.
//
// ASSUMPTIONS:
//   • The Salary Structure Assignment doctype has fields:
//       employee, salary_structure, from_date, base, company
//   • The most recent active assignment is fetched by ordering
//     by from_date descending.
//   • A new assignment is inserted (not amending the old one)
//     so there is a clear audit trail.
//   • When the disciplinary matter is resolved, HR must manually
//     create a new assignment to restore full pay.

function add_half_pay_button(frm) {
    frm.add_custom_button(__('Half Pay'), function () {

        // Step 1: fetch current Salary Structure Assignment
        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype:          'Salary Structure Assignment',
                filters: [
                    ['employee',  '=', frm.doc.employee],
                    ['docstatus', '=', 1]          // only submitted assignments
                ],
                fields:           ['name', 'salary_structure', 'base', 'from_date', 'company'],
                order_by:         'from_date desc',
                limit_page_length: 1
            },
            callback(r) {
                if (!r.message || r.message.length === 0) {
                    frappe.msgprint({
                        title:     __('No Salary Structure Assignment Found'),
                        indicator: 'orange',
                        message:   __(
                            `No submitted Salary Structure Assignment found for ` +
                            `<b>${frm.doc.employee_name}</b>. Please assign a salary ` +
                            `structure before initiating half pay.`
                        )
                    });
                    return;
                }

                const current = r.message[0];

                if (!current.base || current.base <= 0) {
                    frappe.msgprint({
                        title:     __('Base Salary Not Set'),
                        indicator: 'orange',
                        message:   __(
                            `The current Salary Structure Assignment (<b>${current.name}</b>) ` +
                            `does not have a base amount set. Please update the assignment ` +
                            `before using Half Pay.`
                        )
                    });
                    return;
                }

                const full_base = current.base;
                const half_base = full_base / 2;

                // Step 2: confirm with the user, showing current vs half-pay amounts
                frappe.confirm(
                    `<b>Half Pay — Salary Structure Update</b><br><br>
                    <table style="width:100%;border-collapse:collapse;font-size:13px;">
                        <tr>
                            <td style="padding:4px 8px;color:#666;">Employee</td>
                            <td style="padding:4px 8px;font-weight:600;">${frm.doc.employee_name}</td>
                        </tr>
                        <tr style="background:#f9f9f9;">
                            <td style="padding:4px 8px;color:#666;">Current Base</td>
                            <td style="padding:4px 8px;font-weight:600;">
                                ${frappe.format(full_base, { fieldtype: 'Currency' })}
                            </td>
                        </tr>
                        <tr>
                            <td style="padding:4px 8px;color:#666;">Half Pay Base</td>
                            <td style="padding:4px 8px;font-weight:600;color:#C0392B;">
                                ${frappe.format(half_base, { fieldtype: 'Currency' })}
                            </td>
                        </tr>
                        <tr style="background:#f9f9f9;">
                            <td style="padding:4px 8px;color:#666;">Salary Structure</td>
                            <td style="padding:4px 8px;">${current.salary_structure}</td>
                        </tr>
                    </table><br>
                    A new Salary Structure Assignment will be created at <b>50% base pay</b>. 
                    The previous assignment remains as a record. 
                    <br><br>
                    <b>Note:</b> You will need to manually restore full pay once the 
                    disciplinary matter is resolved.`,

                    function () {
                        // Step 3: show a dialog to confirm the effective date
                        let d = new frappe.ui.Dialog({
                            title: 'Confirm Half Pay Effective Date',
                            fields: [
                                {
                                    fieldtype:   'Date',
                                    fieldname:   'from_date',
                                    label:       'Effective From',
                                    reqd:        1,
                                    default:     frappe.datetime.get_today(),
                                    description: 'The date from which the half-pay salary structure takes effect.'
                                },
                                {
                                    fieldtype:   'Small Text',
                                    fieldname:   'reason',
                                    label:       'Reason',
                                    reqd:        1,
                                    default:     `Half Pay — Disciplinary Case ${frm.doc.name}`
                                }
                            ],
                            primary_action_label: 'Apply Half Pay',
                            primary_action(values) {

                                // Step 4: insert new Salary Structure Assignment at 50%
                                frappe.call({
                                    method: 'frappe.client.insert',
                                    args: {
                                        doc: {
                                            doctype:           'Salary Structure Assignment',
                                            employee:          frm.doc.employee,
                                            salary_structure:  current.salary_structure,
                                            company:           current.company,
                                            from_date:         values.from_date,
                                            base:              half_base,
                                            // Store the reason in a custom field if it exists;
                                            // harmless if the field is absent
                                            half_pay_reason:   values.reason,
                                            disciplinary_case: frm.doc.name
                                        }
                                    },
                                    callback(r) {
                                        if (r.exc) return;

                                        const new_name = r.message.name;

                                        // Step 5: submit the new assignment
                                        frappe.call({
                                            method: 'frappe.client.submit',
                                            args:   { doctype: 'Salary Structure Assignment', name: new_name },
                                            callback(res) {
                                                d.hide();

                                                if (res.exc) {
                                                    frappe.msgprint({
                                                        title:     __('Assignment Created but Not Submitted'),
                                                        indicator: 'orange',
                                                        message:   __(
                                                            `Half Pay assignment <b>${new_name}</b> was created ` +
                                                            `but could not be submitted automatically. ` +
                                                            `Please open and submit it manually.`
                                                        )
                                                    });
                                                    window.open(
                                                        `/app/salary-structure-assignment/${new_name}`,
                                                        '_blank'
                                                    );
                                                    return;
                                                }

                                                frappe.show_alert({
                                                    message: __(
                                                        `Half Pay applied. New assignment <b>${new_name}</b> ` +
                                                        `effective ${values.from_date}.`
                                                    ),
                                                    indicator: 'green'
                                                }, 8);

                                                // Open the new assignment for reference
                                                window.open(
                                                    `/app/salary-structure-assignment/${new_name}`,
                                                    '_blank'
                                                );
                                            }
                                        });
                                    }
                                });
                            }
                        });
                        d.show();
                    }
                );
            }
        });

    }, __('HR Actions'));
}


