// ── Debounce utility ─────────────────────────────────────────
const _debounce_timers = {};
function debounce_call(key, fn, delay_ms) {
    if (_debounce_timers[key]) clearTimeout(_debounce_timers[key]);
    _debounce_timers[key] = setTimeout(fn, delay_ms || 600);
}


