// ============================================================
// SUMMARY DISMISSAL FLAG HELPER
// ============================================================

function update_summary_dismissal_flag(frm) {
    const has_sd = has_summary_dismissal(frm) ? 1 : 0;
    if (frm.fields_dict['has_summary_dismissal']) {
        frm.set_value('has_summary_dismissal', has_sd);
    }
}

function has_summary_dismissal(frm) {
    return (frm.doc.charge_description || []).some(
        row => row.prescribed_sanction === 'Summary Dismissal'
    );
}

function guard_summary_dismissal(frm) {
    if (frm.doc.workflow_state === 'Exculpation Evaluation' && has_summary_dismissal(frm)) {
        frappe.msgprint({
            title: __('⚠ Summary Dismissal — Hearing Required'),
            indicator: 'red',
            message: __(
                'One or more charges carry a <b>Summary Dismissal</b> sanction. ' +
                'This case <b>must proceed to a Disciplinary Hearing</b> regardless of the ' +
                'exculpation outcome. You may only select <b>"Non Satisfactory and Dismissible"</b>.'
            )
        });
        return false;
    }
    return true;
}


// ============================================================
// MANDATORY FIELD VALIDATION BY WORKFLOW STATE
// ============================================================

function validate_mandatory_by_state(frm) {
    const state = frm.doc.workflow_state;

    if (state === 'Charge') {
        if (!frm.doc.charge_description || frm.doc.charge_description.length === 0) {
            frappe.msgprint({
                title: __('Validation Error'),
                indicator: 'red',
                message: __('Please add at least one charge in the <b>Charge Description</b> table before proceeding.')
            });
            frappe.validated = false;
            return;
        }

        for (let i = 0; i < frm.doc.charge_description.length; i++) {
            const row = frm.doc.charge_description[i];
            if (!row.specific_offence) {
                frappe.msgprint({
                    title: __('Validation Error'),
                    indicator: 'red',
                    message: __(`Row ${i + 1} in Charge Description is missing the <b>Specific Offence</b>.`)
                });
                frappe.validated = false;
                return;
            }
        }
    }

    if (state === 'Exculpation Evaluation') {
        if (!frm.doc.select_outcome) {
            frappe.msgprint({
                title: __('Validation Error'),
                indicator: 'red',
                message: __('Please select the <b>Exculpation Outcome</b> before saving.')
            });
            frappe.validated = false;
            return;
        }
    }
}


// ============================================================
// BREACH CALCULATION
// ============================================================

function calculate_breach_number(frm, row, cdt, cdn) {
    if (!frm.doc.employee || !row.specific_offence) return;

    const today = frappe.datetime.get_today();

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Disciplinary',
            filters: [
                ['employee',       '=',  frm.doc.employee],
                ['name',           '!=', frm.doc.name || ''],
                ['workflow_state', '=',  'Case Closed']
            ],
            fields: ['name'],
            limit_page_length: 200
        },
        callback(r) {
            if (!r.message || r.message.length === 0) {
                set_breach_and_sanction(frm, cdt, cdn, row, '1st Breach');
                return;
            }

            const prior_case_names = r.message.map(d => d.name);
            let   active_warnings  = [];
            let   pending_calls    = prior_case_names.length;

            prior_case_names.forEach((case_name) => {
                frappe.db.get_doc('Disciplinary', case_name).then((prior_doc) => {
                    if (prior_doc && prior_doc.charge_description) {
                        prior_doc.charge_description.forEach((charge) => {
                            if (charge.specific_offence !== row.specific_offence) return;

                            const expiry = charge.warning_expiry_date;
                            if (!expiry) return;

                            const expiry_obj = frappe.datetime.str_to_obj(expiry);
                            const today_obj  = frappe.datetime.str_to_obj(today);

                            if (expiry_obj >= today_obj) {
                                active_warnings.push({
                                    sanction: charge.prescribed_sanction,
                                    expiry,
                                    case: case_name
                                });
                            }
                        });
                    }

                    pending_calls--;

                    if (pending_calls === 0) {
                        const breach_count  = active_warnings.length + 1;
                        const breach_map    = { 1: '1st Breach', 2: '2nd Breach', 3: '3rd Breach', 4: '4th Breach' };
                        const breach_number = breach_map[breach_count] || '4th Breach';

                        set_breach_and_sanction(frm, cdt, cdn, row, breach_number);

                        if (active_warnings.length > 0) {
                            frappe.msgprint({
                                title: __('Active Prior Warnings Found'),
                                indicator: 'orange',
                                message: __(
                                    `Found <b>${active_warnings.length}</b> active prior warning(s) ` +
                                    `for <b>${row.specific_offence}</b> in closed cases. ` +
                                    `Breach set to <b>${breach_number}</b>.`
                                )
                            });
                        }
                    }
                });
            });
        }
    });
}

function set_breach_and_sanction(frm, cdt, cdn, row, breach_number) {
    frappe.model.set_value(cdt, cdn, 'breach_number', breach_number);

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Offence Sanction Matrix',
            filters: [
                ['offence',        '=', row.specific_offence],
                ['breach_number',  '=', breach_number]
            ],
            fields: ['prescribed_sanction'],
            limit_page_length: 1
        },
        callback(r) {
            if (r.message && r.message.length > 0) {
                const sanction = r.message[0].prescribed_sanction;
                frappe.model.set_value(cdt, cdn, 'prescribed_sanction', sanction);
                set_warning_expiry(cdt, cdn, sanction);

                if (sanction === 'Summary Dismissal') {
                    update_summary_dismissal_flag(frm);
                    frappe.msgprint({
                        title: __('⚠ Summary Dismissal'),
                        indicator: 'red',
                        message: __(
                            `The prescribed sanction for <b>${row.specific_offence}</b> ` +
                            `(${breach_number}) is <b>Summary Dismissal</b>. ` +
                            `This case will proceed to a Disciplinary Hearing.`
                        )
                    });
                }
            } else {
                frappe.msgprint({
                    title: __('Sanction Not Found'),
                    indicator: 'orange',
                    message: __(
                        `No sanction found for <b>${row.specific_offence}</b> at ` +
                        `<b>${breach_number}</b>. Verify the Offence Sanction Matrix.`
                    )
                });
            }
            frm.refresh_field('charge_description');
        }
    });
}

function fetch_prescribed_sanction(frm, cdt, cdn, row) {
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Offence Sanction Matrix',
            filters: [
                ['offence',       '=', row.specific_offence],
                ['breach_number', '=', row.breach_number]
            ],
            fields: ['prescribed_sanction'],
            limit_page_length: 1
        },
        callback(r) {
            if (r.message && r.message.length > 0) {
                frappe.model.set_value(cdt, cdn, 'prescribed_sanction', r.message[0].prescribed_sanction);
                set_warning_expiry(cdt, cdn, r.message[0].prescribed_sanction);
                frm.refresh_field('charge_description');
            }
        }
    });
}

function set_warning_expiry(cdt, cdn, sanction) {
    let expiry_date = null;
    const today = frappe.datetime.get_today();
    const s = (sanction || '').toLowerCase();

    if (s.includes('verbal warning')) {
        expiry_date = frappe.datetime.add_months(today, 6);
    } else if (s.includes('final warning') || s.includes('written warning')) {
        expiry_date = frappe.datetime.add_months(today, 12);
    }
    frappe.model.set_value(cdt, cdn, 'warning_expiry_date', expiry_date);
}


// ============================================================
// POPULATE VERDICT TABLES
// ============================================================

function populate_verdict_from_charges(frm) {
    if (!frm.doc.charge_description || frm.doc.charge_description.length === 0) return;

    const existing = (frm.doc.hearing_outcome || [])
        .map(r => r.specific_offence)
        .filter(Boolean);

    let added = 0;
    frm.doc.charge_description.forEach((charge) => {
        if (!charge.specific_offence) return;
        if (existing.includes(charge.specific_offence)) return;

        let new_row = frm.add_child('hearing_outcome');
        frappe.model.set_value(new_row.doctype, new_row.name, 'specific_offence', charge.specific_offence);
        frappe.model.set_value(new_row.doctype, new_row.name, 'deescription', charge.description);
        frappe.model.set_value(new_row.doctype, new_row.name, 'breach_number', charge.breach_number);
        frappe.model.set_value(new_row.doctype, new_row.name, 'prescribed_sanction', charge.prescribed_sanction);
        frappe.model.set_value(new_row.doctype, new_row.name, 'charge_comments', charge.comments);
        existing.push(charge.specific_offence);
        added++;
    });

    if (added > 0) {
        frm.refresh_field('hearing_outcome');
    }
}

function populate_appeal_verdict_from_verdict(frm) {
    if (!frm.doc.hearing_outcome || frm.doc.hearing_outcome.length === 0) return;

    const existing = (frm.doc.appeal_verdict || [])
        .map(r => r.specific_offence)
        .filter(Boolean);

    let added = 0;
    frm.doc.hearing_outcome.forEach((verdict) => {
        if (!verdict.specific_offence) return;
        if (existing.includes(verdict.specific_offence)) return;

        let new_row = frm.add_child('appeal_verdict');
        frappe.model.set_value(new_row.doctype, new_row.name, 'specific_offence', verdict.specific_offence);
        frappe.model.set_value(new_row.doctype, new_row.name, 'description', verdict.deescription);
        frappe.model.set_value(new_row.doctype, new_row.name, 'breach_number', verdict.breach_number);
        frappe.model.set_value(new_row.doctype, new_row.name, 'prescribed_sanction', verdict.prescribed_sanction);
        frappe.model.set_value(new_row.doctype, new_row.name, 'original_verdict', verdict.verdict);
        frappe.model.set_value(new_row.doctype, new_row.name, 'original_verdict_notes', verdict.hearing_notes || '');
        existing.push(verdict.specific_offence);
        added++;
    });

    if (added > 0) {
        frm.refresh_field('appeal_verdict');
    }
}


// ============================================================
// WORKFLOW STATE CHANGE HANDLER
// ============================================================

function handle_workflow_state_change(frm) {
    const state = frm.doc.workflow_state;

    if (state === 'Issue Warning') {
        show_warning_prompt(
            frm,
            'Warning',
            'warning',
            `A warning is being issued to <b>${frm.doc.employee_name || frm.doc.employee}</b>. ` +
            `Enter the formal warning statement to be recorded in the Warning tab:`
        );
    }

    if (state === 'Outcome Evaluation') {
        show_warning_prompt(frm, 'Hearing Warning', 'hearing_warning', 'Enter the hearing warning statement:');
    }

    if (state === 'Exculpation Evaluation') {
        frm.page.btn_primary.off('click.sd_guard').on('click.sd_guard', function () {
            if (has_summary_dismissal(frm)) {
                guard_summary_dismissal(frm);
            }
        });
    }

    if (state === 'Hearing Outcome') {
        populate_verdict_from_charges(frm);
    }
    if (state === 'Appeal Outcome') {
        populate_appeal_verdict_from_verdict(frm);
    }

    show_stage_guidance(frm);
}


