function setup_custom_buttons(frm) {
    if (frm.is_new()) return;

    const state = frm.doc.workflow_state;

    if (state === 'Hearing Outcome') {
        frm.add_custom_button(__('Populate Verdict Table'), () => {
            populate_verdict_from_charges(frm);
            frappe.show_alert({ message: __('Verdict table populated from charges.'), indicator: 'green' }, 4);
        }, __('Actions'));
    }

    if (state === 'Appeal Outcome') {
        frm.add_custom_button(__('Populate Appeal Verdict'), () => {
            populate_appeal_verdict_from_verdict(frm);
            frappe.show_alert({ message: __('Appeal verdict table populated from hearing outcomes.'), indicator: 'green' }, 4);
        }, __('Actions'));
    }

    if (state === 'Pending CEO Approval') {
        frm.add_custom_button(__('Record Rejection Reason'), () => {
            show_ceo_rejection_prompt(frm);
        }, __('Actions'));
    }

    const sd_states = ['Awaiting Employee Decision', 'Case Closed'];
    if (sd_states.includes(state) && outcome_is_summary_dismissal(frm)) {
        frm.add_custom_button(__('Create Employee Separation'), () => {
            create_employee_separation(frm);
        }, __('Summary Dismissal Actions'));

        frm.add_custom_button(__('Trigger Forced Leave'), () => {
            trigger_forced_leave(frm);
        }, __('Summary Dismissal Actions'));
    }

    if (frm.doc.employee) {
        frm.add_custom_button(__('View Breach History'), () => {
            show_breach_history(frm);
        }, __('Actions'));
    }

    if (state !== 'Draft') {
        frm.add_custom_button(__('Print Case Summary'), () => {
            const url = `/printview?doctype=Disciplinary&name=${frm.doc.name}&format=Disciplinary Report&no_letterhead=0`;
            window.open(url, '_blank');
        }, __('Actions'));
    }
}


