function show_breach_history(frm) {
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype:           'Disciplinary',
            filters:           [['employee', '=', frm.doc.employee], ['name', '!=', frm.doc.name || '']],
            fields:            ['name', 'workflow_state', 'creation'],
            order_by:          'creation desc',
            limit_page_length: 100
        },
        callback(r) {
            if (!r.message || r.message.length === 0) {
                frappe.msgprint(__('No prior disciplinary cases found for this employee.'));
                return;
            }

            let table_html = `
                <table class="table table-bordered table-sm">
                    <thead>
                        <tr>
                            <th>Case</th>
                            <th>Date of Occurrence</th>
                            <th>Status</th>
                            <th>Charges</th>
                        </tr>
                    </thead>
                    <tbody>`;

            let pending   = r.message.length;
            let rows_html = [];

            r.message.forEach((doc, idx) => {
                frappe.db.get_doc('Disciplinary', doc.name).then((full_doc) => {
                    const charges = (full_doc.charge_description || []).map(c =>
                        `<li>
                            ${c.specific_offence} — ${c.breach_number} — <b>${c.prescribed_sanction}</b>
                            ${c.warning_expiry_date ? ' <span style="color:#666;">(Expires: ' + c.warning_expiry_date + ')</span>' : ''}
                        </li>`
                    ).join('');

                    const status_color = doc.workflow_state === 'Case Closed' ? '#27ae60' : '#e67e22';

                    rows_html[idx] = `<tr>
                        <td>
                            <a href="/app/disciplinary/${doc.name}" target="_blank">${doc.name}</a>
                        </td>
                        <td>${doc.creation || '-'}</td>
                        <td>
                            <span style="color:${status_color};font-weight:600;">
                                ${doc.workflow_state}
                            </span>
                        </td>
                        <td><ul style="margin:0;padding-left:16px;">${charges}</ul></td>
                    </tr>`;

                    pending--;
                    if (pending === 0) {
                        table_html += rows_html.join('') + '</tbody></table>';
                        frappe.msgprint({
                            title:   __(`Breach History — ${frm.doc.employee_name}`),
                            message: table_html,
                            wide:    true
                        });
                    }
                });
            });
        }
    });
}


