function render_case_summary(frm) {
    const field = frm.fields_dict.case_summary;
    if (!field) return;
    const doc = frm.doc;

    function val(v) {
        return v ? frappe.utils.escape_html(String(v)) : '—';
    }
    function truncate(str, n) {
        if (!str) return '';
        const plain = String(str).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
        return plain.length > n ? plain.substring(0, n) + '…' : plain;
    }

    const state = doc.workflow_state || '';
    const hasWarning = !!doc.warning;
    const hasHearing = !!(doc.hearing_date || (doc.hearing && doc.hearing.length));
    const hasAppeal = !!doc.grounds_for_appeal;
    const hearingDecision = doc.hearing_decision || '';
    const appealDecision = doc.appeal_decision || '';

    // ── Charges ──────────────────────────────────────────────────────
    let chargesHtml = '<li class="csb-empty">No charges recorded</li>';
    if (doc.charge_description && doc.charge_description.length) {
        chargesHtml = doc.charge_description
            .map((row) => `<li>${val(row.specific_offence || row.description || '(unnamed charge)')}</li>`)
            .join('');
    }

    // ── Timeline ─────────────────────────────────────────────────────
    const tlItems = [];
    function addItem(cls, label, content, meta, quote) {
        tlItems.push(`
            <div class="tl-item ${cls}">
                <div class="tl-label ${cls}">${label}</div>
                <div class="tl-content">${content}</div>
                ${meta ? `<div class="tl-meta">${meta}</div>` : ''}
                ${quote ? `<div class="tl-quote">${truncate(quote, 200)}</div>` : ''}
            </div>`);
    }

    addItem(
        '',
        'Charge Raised',
        `Charge preferred against <strong>${val(doc.employee_name)}</strong> by supervisor <strong>${val(doc.name_of_charging_officer)}</strong>.`,
        doc.response_deadline ? `Response deadline: ${val(doc.response_deadline)}` : null
    );

    const postCharge = ["Recommendation of Charge", "Issue Charge", "Awaiting Exculpation", "Exculpation Evaluation", "Issue Warning", "Recommend Disciplinary Hearing", "Disciplinary Committee", "Set Hearing Date", "Hearing Outcome", "Pending CEO Approval", "Awaiting Employee Decision", "Grounds for Appeal", "Appeal Under Review", "Appeal Requested", "Set Appeal Date", "Pending Outcome Approval", "Appeal Outcome", "Case Closed"];
    if (postCharge.includes(state)) {
        addItem('', 'Charge Reviewed by HR Manager', 'Charge recommendation submitted and reviewed by HR Manager.');
    }

    const postIssue = ["Awaiting Exculpation", "Exculpation Evaluation", "Issue Warning", "Recommend Disciplinary Hearing", "Disciplinary Committee", "Set Hearing Date", "Hearing Outcome", "Pending CEO Approval", "Awaiting Employee Decision", "Grounds for Appeal", "Appeal Under Review", "Appeal Requested", "Set Appeal Date", "Pending Outcome Approval", "Appeal Outcome", "Case Closed"];
    if (postIssue.includes(state)) {
        addItem(
            '',
            'Charge Formally Issued',
            'Charge letter formally issued to employee. Employee awaiting response.',
            doc.issued_by ? `Issued by: ${val(doc.issued_by)}` : null
        );
    }

    const postResponse = ["Exculpation Evaluation", "Issue Warning", "Recommend Disciplinary Hearing", "Disciplinary Committee", "Set Hearing Date", "Hearing Outcome", "Pending CEO Approval", "Awaiting Employee Decision", "Grounds for Appeal", "Appeal Under Review", "Appeal Requested", "Set Appeal Date", "Pending Outcome Approval", "Appeal Outcome", "Case Closed"];
    if (postResponse.includes(state)) {
        addItem(
            '',
            'Employee Submitted Response (Exculpation)',
            'Employee submitted their written response to the charge.',
            doc.select_outcome ? `Supervisor evaluation: ${val(doc.select_outcome)}` : null,
            doc.employee_response
        );
    }

    if (hasWarning) {
        addItem(
            'branch-warning',
            'Warning Issued (No Hearing Required)',
            'Following evaluation of the exculpation, the supervisor determined a formal warning was sufficient.',
            null,
            doc.warning
        );
    }

    if (hasHearing) {
        addItem(
            'branch-hearing',
            'Referred to Disciplinary Hearing',
            'Case escalated. Disciplinary hearing committee appointed.',
            doc.hearing_date ? `Hearing date: ${val(doc.hearing_date)}${doc.hearing_venue ? ' at ' + val(doc.hearing_venue) : ''}` : null
        );
        if (hearingDecision) {
            addItem(
                'branch-hearing',
                'Hearing Outcome',
                'Disciplinary committee reached a decision.',
                `Decision: <strong>${val(hearingDecision)}</strong>`,
                doc.hearing_summary
            );
        }
        if (doc.hearing_outcome && doc.hearing_outcome.length) {
            const verdicts = doc.hearing_outcome
                .map((r) => `${val(r.specific_offence)}: ${val(r.guilty)}`)
                .join('  |  ');
            addItem('branch-hearing', 'Individual Charge Verdicts', verdicts);
        }
    }

    if (hasAppeal) {
        addItem(
            'branch-appeal',
            'Employee Lodged Appeal',
            'Employee exercised right of appeal against the hearing decision.',
            null,
            doc.grounds_for_appeal
        );
        if (doc.appeal_date) {
            addItem(
                'branch-appeal',
                'Appeal Hearing Scheduled',
                'Appeal committee convened.',
                `Date: ${val(doc.appeal_date)}${doc.appeal_venue ? ' at ' + val(doc.appeal_venue) : ''}`
            );
        }
        if (appealDecision) {
            addItem(
                'branch-appeal',
                'Appeal Outcome',
                'Appeal committee reached a decision.',
                `Decision: <strong>${val(appealDecision)}</strong>`,
                doc.final_remarks
            );
        }
    }

    if (state === 'Case Closed') {
        addItem('branch-closed', 'Case Closed', 'All stages completed. Case officially closed.');
    }

    // ── Outcome ribbon ───────────────────────────────────────────────
    let ribbonText = '';
    let ribbonClass = 'outcome-closed';
    if (hasAppeal && appealDecision) {
        ribbonText = `⚖️ Outcome after Appeal: ${val(appealDecision)}`;
        ribbonClass = 'outcome-appeal';
    } else if (hearingDecision) {
        ribbonText = `🏛️ Hearing Decision: ${val(hearingDecision)}`;
        ribbonClass = 'outcome-hearing';
    } else if (hasWarning) {
        ribbonText = '⚠️ Outcome: Formal Warning Issued';
        ribbonClass = 'outcome-warning';
    } else if (state === 'Case Closed') {
        ribbonText = '✅ Case Closed';
        ribbonClass = 'outcome-noaction';
    } else {
        ribbonText = `🔄 In Progress: ${val(state)}`;
        ribbonClass = 'outcome-closed';
    }

    // ── Verdict box ──────────────────────────────────────────────────
    const finalDecision = hasAppeal && appealDecision ? appealDecision : hearingDecision;
    let verdictHtml = '';
    if (finalDecision || hasWarning) {
        let sub = '';
        if (hasAppeal && appealDecision) {
            sub = `Appeal verdict — original hearing decision: ${val(hearingDecision)}`;
        } else if (hasWarning && !hasHearing) {
            sub = 'Warning path — no disciplinary hearing was convened.';
        }
        verdictHtml = `
            <div class="verdict-box">
                <div class="vb-title">Final Outcome / Verdict</div>
                <div class="vb-decision">${val(finalDecision || 'Formal Warning')}</div>
                ${sub ? `<div class="vb-sub">${sub}</div>` : ''}
            </div>`;
    }

    // ── Narrative ────────────────────────────────────────────────────
    const parts = [];
    parts.push(
        `This disciplinary case (<strong>${val(doc.name)}</strong>) was raised against <strong>${val(doc.employee_name)}</strong>` +
        (doc.department ? ` of the <strong>${val(doc.department)}</strong> department` : '') +
        ` by supervisor <strong>${val(doc.name_of_charging_officer)}</strong>.`
    );
    if (doc.charge_description && doc.charge_description.length) {
        const chargeNames = doc.charge_description.map((r) => r.specific_offence || r.description || '(unnamed)');
        parts.push(
            chargeNames.length === 1
                ? `The charge preferred was: <em>${val(chargeNames[0])}</em>.`
                : `The charges preferred were: <em>${chargeNames.map(val).join(', ')}</em>.`
        );
    }
    if (postResponse.includes(state)) {
        parts.push(
            'The employee submitted a written response (exculpation)' +
            (doc.select_outcome ? `, which was evaluated as <strong>${val(doc.select_outcome)}</strong>` : '') +
            '.'
        );
    }
    if (hasWarning && !hasHearing) {
        parts.push('Based on the evaluation, the supervisor determined that a <strong>formal warning</strong> was sufficient to resolve the matter without escalating to a disciplinary hearing.');
    }
    if (hasHearing) {
        parts.push(
            'The case was escalated to a <strong>disciplinary hearing</strong>' +
            (doc.hearing_date ? ` held on <strong>${val(doc.hearing_date)}</strong>` : '') +
            (doc.hearing_venue ? ` at <strong>${val(doc.hearing_venue)}</strong>` : '') +
            '.' +
            (hearingDecision ? ` The hearing committee reached a decision of <strong>${val(hearingDecision)}</strong>.` : '')
        );
    }
    if (hasAppeal) {
        parts.push(
            'The employee <strong>lodged an appeal</strong> against the hearing decision.' +
            (doc.appeal_date ? ` The appeal hearing was held on <strong>${val(doc.appeal_date)}</strong>.` : '') +
            (appealDecision ? ` The appeal committee ruled: <strong>${val(appealDecision)}</strong>.` : '')
        );
    }
    if (state === 'Case Closed') {
        parts.push('The case has been <strong>closed</strong>.');
    } else {
        parts.push(`The case is currently at the <strong>${val(state)}</strong> stage.`);
    }

    // ── Assemble ─────────────────────────────────────────────────────
    const html = `
        <style>
        .case-summary-block {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, sans-serif;
            font-size: 13px; color: #2c3e50; line-height: 1.6; max-width: 900px;
        }
        .case-summary-block .csb-header {
            background: #1a3aad; color: #fff; padding: 14px 20px;
            border-radius: 6px 6px 0 0; display: flex; align-items: center; gap: 12px;
        }
        .case-summary-block .csb-header img.rea-logo {
            max-height: 40px; background: #fff; border-radius: 4px; padding: 3px 6px;
        }
        .case-summary-block .csb-header-text { flex: 1; }
        .case-summary-block .csb-header h2 { font-size: 15px; font-weight: 700; letter-spacing: 0.5px; margin: 0; }
        .case-summary-block .csb-header .case-ref { font-size: 11px; opacity: 0.85; }
        .case-summary-block .outcome-ribbon {
            padding: 8px 20px; font-size: 13px; font-weight: 700; text-align: center;
            letter-spacing: 0.5px; margin-bottom: 16px; border-radius: 0 0 4px 4px;
        }
        .case-summary-block .outcome-warning  { background:#fef3cd; color:#856404; border:1px solid #f0c14b; }
