// Restrict disciplinary / appeal committee selection.
//  - REA 3/4/5+  : employees of the required grade band (mirrors Server Script "Disciplinary Committee Composition")
//  - REA 1/2     : users holding the "Disciplinary Board Member" role (Board Member column)

const DISC_MEMBER_BAND = {
    "REA 3": "REA 2",
    "REA 4": "REA 3",
    "REA 5": "REA 4", "REA 6": "REA 4", "REA 7": "REA 4",
    "REA 8": "REA 4", "REA 9": "REA 4", "REA 10": "REA 4",
};
const DISC_CHAIR_BAND = {
    "REA 3": "REA 2",
    "REA 4": "REA 3",
    "REA 5": "REA 3", "REA 6": "REA 3", "REA 7": "REA 3",
    "REA 8": "REA 3", "REA 9": "REA 3", "REA 10": "REA 3",
};
const DISC_CHAIR_ROLE = { "REA 1": "Board Chairperson", "REA 2": "HR Board Committee Chairperson" };
const DISC_BOARD_GRADES = ["REA 1", "REA 2"];
const DISC_BOARD_ROLE = "Disciplinary Board Member";
const DISC_COMMITTEE_TABLES = ["hearing", "appeal_members"];

function disc_apply_committee_queries(frm) {
    DISC_COMMITTEE_TABLES.forEach((tf) => {
        if (!frm.fields_dict[tf]) return;

        frm.set_query("employee", tf, (doc, cdt, cdn) => {
            const row = locals[cdt] && locals[cdt][cdn];
            const band = DISC_MEMBER_BAND[frm._offender_grade];
            const filters = { status: "Active" };
            if (frm.doc.employee) filters.name = ["!=", frm.doc.employee];
            // Secretary is non-adjudicating: any grade may be picked (set "Role in the Committee" first)
            const role = row && row.role_in_the_committee;
            const target = role === "Chairperson" ? DISC_CHAIR_BAND[frm._offender_grade] : band;
            if (target && role !== "Secretary") filters.grade = target;
            return { filters };
        });

        frm.set_query("custom_board_member", tf, (doc, cdt, cdn) => {
            const row = locals[cdt] && locals[cdt][cdn];
            const filters = { enabled: 1 };
            const chair_role = DISC_CHAIR_ROLE[frm._offender_grade];
            const users = (row && row.role_in_the_committee === "Chairperson" && chair_role)
                ? (frm._board_users_by_role || {})[chair_role]
                : frm._board_users;
            if (Array.isArray(users)) filters.name = ["in", users];
            return { filters };
        });
    });
}

function disc_load_board_users(frm) {
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Has Role",
            filters: { role: ["in", [DISC_BOARD_ROLE, ...Object.values(DISC_CHAIR_ROLE)]], parenttype: "User" },
            fields: ["parent", "role"],
            parent: "User",
            limit_page_length: 0,
        },
        callback(r) {
            const byRole = {};
            (r.message || []).forEach((x) => { (byRole[x.role] = byRole[x.role] || []).push(x.parent); });
            frm._board_users_by_role = byRole;
            frm._board_users = [...new Set((r.message || []).map((x) => x.parent))];
            disc_apply_committee_queries(frm);
        },
        error() {
            frm._board_users = null;   // unknown -> don't over-restrict; server still enforces
            disc_apply_committee_queries(frm);
        },
    });
}

function disc_load_offender_grade(frm) {
    if (!frm.doc.employee) {
        frm._offender_grade = null;
        disc_apply_committee_queries(frm);
        return;
    }
    frappe.db.get_value("Employee", frm.doc.employee, "grade").then((r) => {
        frm._offender_grade = (r && r.message && r.message.grade) || null;
        disc_apply_committee_queries(frm);

        if (DISC_BOARD_GRADES.includes(frm._offender_grade) && !frm.__disc_board_hint) {
            frm.__disc_board_hint = true;
            frappe.show_alert({
                message: __(
                    "{0} matter: the panel is the Board / HR Board Committee - use the Board Member column " +
                    "(users with the '{1}' role), not employees. The Chairperson must hold the '{2}' role.",
                    [frm._offender_grade, DISC_BOARD_ROLE, DISC_CHAIR_ROLE[frm._offender_grade]]
                ),
                indicator: "blue",
            }, 10);
        }
    });
}

frappe.ui.form.on("Disciplinary", {
    onload(frm) {
        disc_load_board_users(frm);
        disc_load_offender_grade(frm);
    },
    refresh(frm) { disc_apply_committee_queries(frm); },
    employee(frm) {
        frm.__disc_board_hint = false;
        disc_load_offender_grade(frm);
    },
});

// HRO - Employee Welfare is usually the committee Secretary: prefill an empty Secretary row (still editable).
const DISC_DEFAULT_SECRETARY_DESIGNATION = "Human Resource Officer - Employee Welfare";
frappe.ui.form.on("Hearing Commitee", {
    role_in_the_committee(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        if (row.role_in_the_committee !== "Secretary" || row.employee || row.custom_board_member) return;
        frappe.db.get_value("Employee",
            { designation: DISC_DEFAULT_SECRETARY_DESIGNATION, status: "Active" }, "name"
        ).then((r) => {
            const emp = r && r.message && r.message.name;
            if (emp && emp !== frm.doc.employee && !locals[cdt][cdn].employee) {
                frappe.model.set_value(cdt, cdn, "employee", emp);
            }
        });
    },
});
